INSERT INTO `data_directory` VALUES (35, '石榴', 'https://etrees.oss-cn-shanghai.aliyuncs.com/7b2416c4-8075-40ba-95f8-9f423659f7da.png', '2023-06-28 17:36:36');
INSERT INTO `data_info` VALUES (108, 16, '番茄', '叶斑病', '茄匐柄霉菌侵染所引起的、发生在番茄上的病害。主要危害叶片，很少危害茎。发病初期叶面布满圆形或不正圆形的暗褐色小斑点，呈水浸状，并沿叶脉向四周扩大，发展为不规则形病斑。连阴天，多雾的早晨及温度忽高忽低变化均有利于该病的发生蔓延。\n', '夏秋季', '由真菌半知菌亚门葡萄孢属的一种真菌侵染引起的，低温高湿条件下易发病。病原菌可借风雨传播，从气孔、皮孔、伤口或表皮侵入，在植株上可多次重复侵染。温暖潮湿，阴雨天及结露持续时间长是发病的重要条件，而高温干燥天气则不利于该病的发生。\n', '选用抗病品种。选用无病种子或播种前进行种子处理。加强田间管理，提高植株抗病性。收获后彻底清除病残体，并深翻土壤。在病害常发地区，可选用药剂预防，如定植后、初果期使用25%嘧菌酯悬浮剂1000-1500倍液喷雾；或75%百菌清可湿性粉剂600倍液灌根。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/b7a8cae1-5628-44d3-a5fe-1007b9eb11d7.JPG', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (109, 15, '葡萄', '黑腐病', '是一种世界性的葡萄病害，各产区普遍发生。该病主要为害叶片、新梢和果实，也为害卷须和叶柄。\n', '春季和秋季', '气候条件：气候是引起葡萄黑腐病发生和流行的重要因素。春季气温回升，树体萌动后开始发病，进入6-7月份，气温升高，病害进入盛发期。此时，降雨和湿度对病害的发生和流行起到重要作用。病原菌：黑腐病的病原菌为一种真菌，菌丝体在病组织中越冬，次年春季产生分生孢子，通过风雨传播。分生孢子可多次萌发，对植株进行再侵染。栽培管理：地势低洼、枝条徒长、架面郁闭、氮肥施用过量等不良栽培管理措施，容易导致病害的发生和流行。品种抗性：不同品种对黑腐病的抗性存在明显差异。\n', '选育抗病品种：根据当地的气候条件和栽培方式，选择对黑腐病抗性较强的品种进行栽培。加强栽培管理：加强葡萄生长期的栽培管理，增强树势，提高抗病能力。同时，及时清除病叶、病果和病枝，减少菌源数量。药剂防治：在葡萄发芽前和生长期，喷洒杀灭性的药剂进行防治。一般使用80%波尔多液、50%保倍福美双（嘧菌酯·福美双）可湿性粉剂、现配波尔多液等。消除菌源：在冬季修剪后，清除枯枝落叶和杂草等，集中烧毁或深埋，以减少菌源数量。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/23cd2c7d-86a1-4fdc-91bf-c4d7e6dd9b47.jpg', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (110, 17, '苹果', '黑星病', '由苹果黑星菌侵染所引起的、发生在苹果上的病害。主要危害叶片、叶柄、果柄、花芽、花器及新梢，从落花期到苹果成熟期均可危害。该病害是世界各苹果产区的重要病害，严重影响苹果品质、产量和贮藏，商品果比例降低。', '5-6月份', '苹果黑星病初次侵染为落叶上子囊果内的子囊孢子，再次侵染由风、雨传播的半知菌亚门真菌分生孢子。温暖潮湿，有利于病菌发展，多雨年份、低洼地及湿度高于85%的条件下发病重。', '及时清园，加强检疫，严禁从病区向无病区携带苗木、接穗和果实。加强栽培管理，增施有机肥，低洼积水地注意及时排水，改良土壤，以增强树势。落叶后及时清扫果园，收集病叶、病果集中烧毁或深埋，以减少病菌的侵染源。采取夏季修剪措施，改善果园通风透光条件，创造有利于树体生长的环境，恶化病菌滋生环境。早熟品种于5月中旬开花期开始喷洒1:2～3:160倍式波尔多液，以后隔15天一次，共喷5次。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/a4d4e7cf-87d9-4fe1-9a04-d9961c40b07a.JPG', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (111, 12, '苹果', '斑点落叶病', '苹果斑点落叶病是一种常见的苹果病害，由真菌感染引起。病原体在潮湿的条件下生长繁殖，导致苹果树叶片上出现带有明显边缘的黄褐色斑点，随着病情加重，这些斑点会扩大并融合，最终叶片黄化、干枯掉落\n', '5月至6月及9月', '病原菌的侵入：斑点落叶病以菌丝体潜伏在落叶中越冬，春季降雨后，病菌孢子开始在落叶中传播，一般在苹果树花后，对新梢进行初次侵染。高温、高湿：有利于苹果斑点病发生。气候条件还有病原的侵入都有可能引起苹果斑点落叶病。苹果树抗病能力差，管理粗放及防治不当等。\n', '秋末冬初清园，夏季剪除徒长枝，减少后期侵染源，改善果园通透性。合理施肥，增强树势，提高抗病能力。在发病前开始喷施波尔多液、代森锌可湿性粉剂600~800倍液、50%多锰锌可湿性粉剂400~600倍液、扑海因可湿性粉剂1000倍液、速克灵可湿性粉剂1000倍液、甲基硫菌灵悬浮剂500~600倍液、菌毒清600倍液、多氧霉素可湿性粉剂1000倍液、3%多氧清水剂800倍液等药剂进行防治。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/37857b2e-27fa-4558-8677-317d9044bcfd.png', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (112, 12, '苹果', '褐斑病', '是由苹果双壳菌侵染所引起的、发生在苹果上的一种病害。主要为害叶片，其次是果实和叶柄。\n', '7-8月', '在降雨量较多且土壤含水量高的地区，病害通常会严重发生。在大风暴雨或浇水后暴晴的天气，会导致病情加重。苹果树缺素导致褐斑病发生，如缺镁、缺铜、缺锌、缺铁等。套袋管理及果园郁闭。化学药品不合理使用：部分果区存在有农药使用量多，药品不对路，时期掌握不当等问题，从而造成早期落叶病发生严重。\n', '选育和换种抗病品种。加强果园管理。清除越冬菌源。合理密植，改善果园通风透光条件。秋季要彻底清除树上、地面落叶，集中烧毁，并喷施护树将军，以消灭越冬菌源。药剂防治，在发病前或初期，交替喷洒70%甲基托布津可湿性粉剂1000倍液或50%多菌灵可湿性粉剂800-1000倍液或25%苯菌灵乳油300-500倍液或75%百菌清可湿性粉剂600-800倍液或2%抗霉菌素水剂200倍液或1：2：200倍波尔多液或70%代森锰锌可湿性粉剂500-600倍液，共喷5次左右，每隔7-10天喷1次。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/5b4a7238-f7fe-47be-b049-a7fb47fa5f99.png', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (113, 12, '苹果', '灰斑病', '苹果灰斑病是一种由真菌感染引起的常见苹果病害，主要发生在潮湿、多雨的环境中。该病害会导致苹果树叶片、果实等部位出现圆形或不规则形状的灰白色病斑，并且病斑周围有黑色晕轮。病斑逐渐扩大，导致果实畸形、变小、变硬、变皱甚至腐烂。\n', '5月中下旬，7～8月', '苹果灰斑病是由真菌引起的，病原菌为梨叶点霉该病菌在病落叶或病枝上越冬，翌年春季产生分生孢子，借风雨传播，侵染叶片、果实和枝条。降雨多、湿度大时，有利于病害发生。苹果灰斑病的发生与降雨量和降雨天数有密切关系。降雨天数多，发病重；降雨量少，发病轻。\n', '彻底清园，秋末冬初结合修剪，清除病枝、病叶、病果等，并集中销毁。加强管理，及时开沟排水，疏花疏果，使通风透光，提高树体的抗病能力。药剂防治，在梨树开花后至5月下旬喷药保护。有效药剂有：50%多菌灵WP或50%甲基硫菌灵WP或70%甲基硫菌灵WP或70%丙森锌WP或70%代森锰锌WP或75%百菌清WP或80%大生M-45WP或1.5%多抗霉素WP。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/c7163a0d-d5e9-4788-9e19-c2816325a515.jpg', 1, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (114, 12, '苹果', '锈病', '由山田胶锈菌侵染所引起的、发生在苹果上的病害。主要为害叶片，也能为害嫩枝、幼果和果柄，还可为害转主寄主桧柏。往往造成早期落叶，弱树量。苹果锈病的流行与早春的气候密切相关，降雨频繁，气温较高易诱发此病流行。相反，春天干燥，虽降雨偏多，气温较低则发病较轻。\n', '早春', '苹果园地势低洼，排水不良，株行间郁闭，通风透光不好，湿度过大，有利于病菌的生长繁殖。苹果园附近种有桧柏树，或距离桧柏树较近，病菌孢子借助风雨传播进行侵染。苹果树衰弱，抗病能力下降，也易感病。长期连续降雨，有利于病害的发生和发展\n', '避免在低洼地种植苹果树，并注意及时排水，以降低园内湿度。在苹果园附近避免种植桧柏树，或距离桧柏树较远，以减少病菌孢子的传播。增强苹果树的树势，提高其抗病能力。\n及时清除病枝、病叶和病果，并集中销毁，以减少病菌的来源。在苹果展叶期开始时，每隔10-15天喷布一次杀菌剂，连喷2-3次，可选用代森锰锌、苯醚甲环唑、氟硅唑等内吸性杀菌剂。在苹果锈病发生严重时，可选用三唑酮、戊唑醇等内吸性杀菌剂进行防治。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/eec9c35a-da79-46f6-a363-2c09fcc51aa4.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (115, 12, '苹果', '棕斑病', '由苹果盘多毛孢侵染所引起的、发生在苹果上的一种病害。主要危害果实、有时也危害叶片。\n', '7月至11月', '降雨：苹果褐斑病发生于降雨和温度关系密切，分生孢子的传播和侵入需要水滴因此，在降雨量大、降雨早、降雨多的年份，苹果棕斑病的发生也早、也重。温度：温度主要影响病害的潜育期，在较高温度下，潜育期短，病害扩展迅速。栽培条件：管理不善，地势低洼，排水不良，造成树势衰弱，发病重。叶龄与叶位：发病与叶龄有一定关系。叶龄35天以内的叶片容易感染发病，11-25天叶龄的叶片最易感病，36天以上的叶片基本不再被侵染。同一株树上当年结果枝上的叶片发病率较歇果枝上的高，树冠内膛下部叶片比外围上部叶片发病早而且多。品种抗性：红玉、金冠、富士、北斗、元帅等品种易感病；祝光、国光、鸡冠、倭锦、青香蕉等发病较轻；小国光则表现抗病。\n', '清除病源：秋季落叶后，结合剪枝剪除病枝和病叶。清扫果园，将枯枝、落叶、落果等集中烧毁或深埋。合理施肥、灌溉：多施有机肥料，合理灌溉。在生长季节不要过量施用氮肥，要增加磷钾肥的施用量，以增强树势，提高树体的抗病能力。雨季要注意开沟排水，防止果园积水，降低果园空气湿度。合理修剪：要注意修剪，使果园通风透光。要合理疏花疏果，避免果树负载过量，防止树势衰弱。药物防治：在病害发生严重时，可用多抗霉素或苯菌灵进行治疗。每隔7-10天喷一次，连喷2-3次。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/8764f8c3-b283-455f-b7da-11b65ea8e96a.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (116, 15, '葡萄', '白粉病', '由葡萄钩丝壳菌侵染所引起的发生在葡萄上的一种病害。主要危害叶片、新梢及果实等幼嫩器官，老叶及着色果实较少受害。\n', '7-9月份', '品种抗性：不同品种的抗病性存在明显差异。菌源数量：病菌数量是白粉病发生的初始条件。天气情况：病害发生的气候条件是高湿度、低温度(15～25 ℃)和较大的昼夜温差(8～15 ℃)。栽培管理：地势低洼、枝条徒长、架面郁闭、氮肥施用过量等都是有利于病害发生的因素。\n', '清除病原：在冬季和夏季修剪时，收集并烧毁或深埋病枝、病叶和病果，以减少菌源数量。加强生长期管理：加强葡萄生长期的水肥管理，增强树势，提高抗病能力。合理修剪，保持通透，避免郁闭。药剂防治：在葡萄发芽前喷洒波美石硫合剂，落花后半个月左右开始喷洒石硫合剂、甲基托布津、代森锰锌等药剂，每隔7-10天喷洒一次，连续喷洒2-3次。及时除草和清理果园：保持果园整洁，及时除草和清理病枝叶，避免二次感染。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/1306ddce-baea-4fd4-8e49-6760ed86ab3f.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (117, 15, '葡萄', '白腐病', '由白腐垫壳孢菌侵染所引起的发生在葡萄上的病害。主要危害果穗，也危害新梢、叶片等部位。\n', '7-9月份', '降雨多，湿度大：降雨是导致白腐病发生和流行的关键因素。伤口多：伤口是白腐病病菌侵入的主要途径之一。菌源多：菌源是白腐病发生的另一个重要因素。品种抗性差：不同品种对白腐病的抗性存在明显差异。\n', '清除病原：在冬季和夏季修剪时，收集并烧毁或深埋病枝、病叶和病果，以减少菌源数量。加强生长期管理：加强葡萄生长期的水肥管理，增强树势，提高抗病能力。合理修剪，保持通透，避免郁闭。药剂防治：在葡萄发芽前喷洒波美石硫合剂，落花后半个月左右开始喷洒石硫合剂、甲基托布津、代森锰锌等药剂，每隔7-10天喷洒一次，连续喷洒2-3次。及时除草和清理果园：保持果园整洁，及时除草和清理病枝叶，避免二次感染。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/f6b39c9e-8f26-422c-8a65-75621dd9ac2a.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (118, 15, '葡萄', '黑痘病', '由葡萄痂囊腔菌侵染所引起的、发生在葡萄上的病害。主要危害葡萄的绿色幼嫩部位，如果实、果梗、叶片、叶柄、新梢和卷须等。\n', '春季和秋季', '气候条件：气候是引起葡萄黑痘病发生和流行的重要因素。春季气温回升，树体萌动后开始发病，进入6-7月份，气温升高，病害进入盛发期。此时，降雨和湿度对病害的发生和流行起到重要作用。病原菌：黑痘病的病原菌为一种真菌，菌丝体在病组织中越冬，次年春季产生分生孢子，通过风雨传播。分生孢子可多次萌发，对植株进行再侵染。栽培管理：地势低洼、枝条徒长、架面郁闭、氮肥施用过量等不良栽培管理措施，容易导致病害的发生和流行。品种抗性：不同品种对黑痘病的抗性存在明显差异。\n', '选育抗病品种：根据当地的气候条件和栽培方式，选择对黑痘病抗性较强的品种进行栽培。加强栽培管理：加强葡萄生长期的栽培管理，增强树势，提高抗病能力。同时，及时清除病叶、病果和病枝，减少菌源数量。药剂防治：在葡萄发芽前和生长期，喷洒杀灭性的药剂进行防治。一般使用80%波尔多液、50%保倍福美双（嘧菌酯·福美双）可湿性粉剂、现配波尔多液等。消除菌源：在冬季修剪后，清除枯枝落叶和杂草等，集中烧毁或深埋，以减少菌源数量。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/049c9b25-33cc-49d6-ac39-5bc878a4b6a8.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (119, 15, '葡萄', '灰霉病', '该病是由半知菌亚门葡萄孢属的一种真菌侵染引起的，主要危害花序、幼果和已经成熟的果实，有时也危害新梢、叶片和果梗。在春季，灰霉病可引起花腐，而在秋季则果实容易感染灰霉病。该病也是造成葡萄贮藏期间果实腐烂的主要因素之一。\n', '春季和秋季都可以发生，其中春季是主要发病季节。', '气候条件：低温、高湿的环境有利于灰霉病的发生和流行。在适宜的温度条件下，高湿和相对湿度达90%以上时，灰霉病发生严重。品种抗性：不同品种对灰霉病的抗性存在明显差异。如巨峰、龙眼等品种易感病，而康拜尔、先锋等品种相对抗病。栽培管理：田间地势低洼、枝条郁闭、杂草丛生、通风透光不良的果园，有利于灰霉病的发生和流行。\n', '清洁田园。在秋季落叶后和冬季修剪后，彻底清扫果园内外的枯枝落叶和杂草，并集中烧毁或深埋。在发芽前喷洒5波美度石硫合剂，清园消毒。合理施肥。施用腐熟的农家肥为主，适量增施磷钾肥。避免偏施氮肥，防止植株徒长，降低抗病性。防治害虫。在生长季节，及时防治蚜虫、卷叶虫等害虫，减少伤口和传播媒介。改善果园环境。高垄栽培，采用滴灌供水，避免大水漫灌。在垄沟里铺一层10cm干秸秆，降低温湿度。药剂防治。在发病初期，选择晴天早晨或傍晚时分，喷洒50%腐霉利可湿性粉剂1000倍液、50%异菌脲可湿性粉剂1000倍液、30%霉腐灵水剂600倍液等。每7-10天喷洒一次，连续喷洒2-3次，直到病害得到控制为止。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/aaa138a7-7c26-4347-8dfa-7ff895acb3d6.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (120, 15, '葡萄', '霜霉病', '是由真菌引起的，主要危害叶片、新梢和果实，造成落叶、梢枯、果穗腐烂和减产，影响果实品质及贮藏性能。\n', '春季和秋季', '气候条件：低温、高湿的环境有利于霜霉病的发生和流行。在适宜的温度条件下，高湿和相对湿度达90%以上时，霜霉病发生严重。品种抗性：不同品种对霜霉病的抗性存在明显差异。如巨峰、龙眼等品种易感病，而康拜尔、先锋等品种相对抗病。栽培管理：田间地势低洼、枝条郁闭、杂草丛生、通风透光不良的果园，有利于霜霉病的发生和流行。\n', '清除菌源：结合冬季修剪，及时清除果园内的病叶、病果和枯枝，集中烧毁或深埋。清园后，对果园喷洒5度石硫合剂，减少菌源。加强栽培管理：加强葡萄树的生长管理，提高植株的抗病能力。增施腐熟的有机肥，避免偏施氮肥，适时补充磷钾肥，促进树体健壮生长。同时，合理修剪，改善果园的通风透光条件。药剂防治：在发病初期，使用50%克菌丹可湿性粉剂500倍液、70%乙磷铝·锰锌可湿性粉剂500倍液、64%杀毒矾可湿性粉剂500倍液等药剂进行喷雾防治。每隔7-10天喷洒一次，连续喷洒2-3次。生物防治：在霜霉病发生前，使用生物农药如农用链霉素、武夷菌素、梧宁霉素等，进行预防。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/2ec13c08-37e3-4bea-839c-e7e51da4b114.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (121, 11, '番茄', '粉末状霉菌', '它是由一种叫做Fusarium oxysporum的真菌引起的。该病害主要影响番茄植物的叶子，有时也影响果实和茎。叶子可能会变成棕色或黑色，并出现小的、凸起的病斑，最终会变成粉红色的粉末。果实可能会变得软化和腐烂，有时也会产生病斑。\n', '花期开始发病', '由真菌半知菌亚门葡萄孢属的一种真菌侵染引起的，低温高湿条件下易发病。病原菌以菌核在土壤或病残体中越夏或越冬，也可在土壤中腐生。 病菌在田间借风雨、气流、接触、沾附等传播蔓延。灰霉病菌对温度适应范围广，发育适温为20～23 ℃，最高35 ℃，最低-5 ℃。湿度发生的决定因素，低温高湿有利于发生和流行，尤其在番茄蘸花后天气忽冷忽热、阴雨连绵、光照不足、日高夜低、相对湿度大于90%时发病迅速。\n', '轮作换茬：可与禾本科作物实行轮作，降低田间菌源基数。摘除花瓣：在蘸花时，用带微孔的泡塑板蘸花，可防止灰霉病菌孢子沾到花瓣上。也可在蘸花药中加入0.1%扑海因或速克灵，有一定的预防作用。发现花瓣染病卷曲时，及时摘除花瓣和柱头，集中深埋或烧毁，以防止病菌再次传播。调节棚室环境：在保证棚室温度的前提下，加大放风量，降低相对湿度。化学防治：在发病初期，可选择以下药剂喷雾防治：50%速克灵可湿性粉剂2000倍液。50%扑海因可湿性粉剂1000倍液。75%百菌清可湿性粉剂600倍液。40%施佳乐悬浮剂1200倍液。38%嘧霉胺悬浮剂800倍液。50%多霉威（多菌灵、万霉灵）可湿性粉剂1000倍液。70%甲基托布津可湿性粉剂800倍液。65%甲霉灵可湿性粉剂1000倍液。72.2%普力克水剂800倍液。50%多菌灵可湿性粉剂800倍液。以上药剂最好交替使用，每5-7天一次，连续喷2-3次。同时，应结合叶面追肥，增强植株的抗病性。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/57d8d4db-c5dd-42dc-867d-48ee33deb314.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (122, 11, '番茄', '立枯病', '主要发生在刚出土的幼苗及大苗，以育苗后期发生偏多。幼苗染病后，茎基部发生褐色凹陷病斑，发病初期茎叶白天菱蔫，夜间恢复正常，经数日反复后，病株就菱蔫枯死。\n', '种植后1到3个月', '连作：连作是导致番茄立枯病发生的主要原因。土壤积水：长期阴雨天气，地势低洼，排水不良，浇水过量等造成土壤积水，导致根系窒息，发生沤根现象，很容易引发番茄立枯病。施肥不合理：施用未腐熟的有机肥，且施肥过量，造成烧根伤根，容易引发番茄立枯病。温度管理不当：棚内温度高，放风不及时，放风量过小，发病较重。幼苗生长不良：幼苗出土后，若因畦面干旱，浇水过多，湿度过大，幼苗生长衰弱，抗病力弱，发病较重。土壤粘重：沙土地或沙性大的土壤发病较少。土壤粘重的发病重。其他因素：上年染病的根结线虫及地下害虫多的地块发病重。\n', '种子处理：用50度温水浸种20分钟，不断搅拌，然后捞起催芽播种。土壤处理：每平方米苗床用8克左右50%多菌灵可湿性粉剂，与细土混合后，1/3药土施入苗床下，2/3药土作覆盖用。改善栽培环境：种子发芽适宜温度为25-28度，芽期和幼苗期白天保持25-30度，夜晚保持16-20度。控制棚内湿度，及时透风排湿，减少叶面结露和吐水。在连续阴雨天后骤然放晴时，要采取逐步升温措施，避免植株“闪死”。苗期管理：控制苗床浇水，并做到定期喷药预防。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/c1c056e2-0d2d-434f-9a34-a15323127217.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (123, 11, '番茄', '叶霉病', '一种由真菌感染引起的常见番茄病害，主要发生在高温多湿的环境中。该病害会导致叶片出现黄褐色水浸状斑点，其表面有灰白色霉层。病斑逐渐扩大，导致叶子变形、卷曲、干枯甚至死亡。', '秋季', '番茄叶霉病病菌喜高温、高湿环境，发病最适气候条件为温度20-25℃，相对湿度95%以上。多年连作、排水不畅、通风不良、田间过于郁闭、空气湿度大的田块发病较重。早春低温多雨、连续阴雨或梅雨多雨的年份发病重。秋季晚秋温度偏高、多雨的年份发病重。\n', '栽培防病。选用抗病品种、播前进行温汤浸种、合理轮作、加强棚室管理等措施，可以有效减缓番茄叶霉病的发生。栽培防病是预防叶霉病发生的重要措施，生产上要选用抗病品种、增施有机肥、培育壮苗；合理密植，及时整枝打叉；加强通风，降低棚内湿度，尽可能的选用膜下暗灌浇水技术；有条件的话，在遭遇连续阴雪天或雾霾天气时采用补光技术等。药剂防治。预防用药是前提，喷施嘧霉胺对预防叶霉病有很好的作用，可喷施40%嘧霉胺可湿性粉剂1000～1200倍液，连喷2～3次，7～10天喷一次，即可有效的预防叶霉病的发生。发病初期及时用药很关键，可使用42.8%氟菌•肟菌脂悬浮剂、42.4%唑醚•氟酰胺悬浮剂、10%多抗霉素可湿性粉剂、47%春雷•王铜可湿性粉剂、250g/l嘧菌酯悬浮剂或50%甲基硫菌灵可湿性粉剂喷雾防治。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/5ae9264a-a64c-4b21-bda6-ba1f020be77a.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (124, 11, '番茄', '早疫病', '是一种由真菌感染引起的常见番茄病害，主要在潮湿天气下发作。该病害会导致叶片出现细黄色斑点，随着病情加重，病斑逐渐融合变成棕色或黑色，表面有粉状的霉层，叶子会逐渐枯黄干瘪。这些症状逐渐扩大到整个植株，最终导致果实变小、变形、变黑甚至腐烂。\n', '高温季节', '是由茄链格孢引起的真菌病害。病原菌以菌丝体或分生孢子在病残体或以菌丝体在种子上越冬，成为翌年的初侵染源。翌年条件适宜时，分生孢子借风、雨传播，从气孔、皮孔及直接侵入等多种方式侵入，引起发病。病菌在田间可辗转为害，引起病害的流行。\n', '选用抗病品种。加强田间管理。与非茄科作物轮作；增施基肥，尤其是磷钾肥；合理密植，避免高秧品种过密；及时整枝打杈、摘除底叶、通风透光；避免在阴雨天浇水，防止空气湿度过大。药物防治。从苗期始，每隔7～10天喷药1次，连续喷药3～4次，每次喷药时要交替使用不同药剂，以防病菌对药剂产生抗性。可用70%代森锰锌可湿性粉剂500倍液、75%百菌清可湿性粉剂600倍液，50%多菌灵可湿性粉剂500倍液、或1∶1∶200倍波尔多液喷雾。保护地栽培番茄还可用45%百菌清烟雾剂，亩用药250克，由里向外逐次点燃烟剂，密闭大棚或温室，熏烟2～3小时，效果显著。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/31939bca-71c6-4c4f-b11c-6ccb73f7bc58.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (125, 11, '番茄', '蜘蛛螨伤害', '番茄蜘蛛螨是一种微小的节肢动物，主要在夏季和早秋时期活动。该害虫主要寄生在番茄的叶片上，以叶肉为食，会导致叶片出现黄褐色斑点和细网状损伤，严重时会导致叶片萎缩和死亡。\n', '高温季节', '番茄蜘蛛螨（Tetranychus telarius）是一种害虫，它们以刺吸式口器吸取番茄植株的汁液，导致植株生长缓慢，叶片发黄，果实变小，并且容易感染病害。它们在高温干燥的环境下繁殖能力更强，因此容易在夏季的高温季节发生为害。此外，如果使用未成熟的油、饼肥等作为基肥，也会导致番茄蜘蛛螨的发生。\n', '清洁田园：及时摘除枯枝、病叶、果实，并将其烧毁或深埋，以减少虫源。药剂防治：在番茄植株定植前，可用5%克螨特乳油1000倍液喷雾防治；在番茄生长期，可用20%螨死净悬浮剂2000倍液、5%尼索朗乳油2000倍液、15%哒螨灵乳油3000倍液等药剂喷雾防治，喷药时要均匀，叶正面和叶背面都要喷到。生物防治：蜘蛛螨的天敌有草蛉、捕食螨、蓟马等，它们可以寄生或捕食蜘蛛螨，因此可以保护或引进这些天敌，以控制蜘蛛螨的数量。栽培防治：在栽培过程中，要注意加强田间管理，合理施肥、浇水，促进植株健壮生长，提高其抗病能力。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/1e3d3c71-5099-43c3-90f3-eea76b3fc01d.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (126, 18, '柑橘', '疮痂病', '是柑橘生产中的一种常见病害，主要危害新梢、果实和叶片。该病的发生与温度、湿度和栽培管理有关。\n', '春季和夏季', '是一种由真菌引起的植物病害，主要危害柑橘类果树的叶、枝和果实。该病的发生与温度、湿度和栽培管理有关。在春季和夏季，气温适宜、湿度较高的环境下，疮痂病的发生较为严重。果园中如果存在病菌，遇到多雨潮湿的天气，病菌会迅速繁殖，导致病害爆发。因此，在多雨季节和潮湿的果园中，柑橘疮痂病的发病率较高。此外，果园管理不善、排水不畅、施肥不当、修剪不足等也会促进该病的发生。\n', '严格检疫：购买果苗时，应选择无病苗木。清洁果园：及时清除病枝、病叶和病果，并烧毁或深埋，减少病菌的传播。药剂防治：在春季和夏季多雨季节来临前，喷施保护性药剂，如波尔多液、石硫合剂等。发现病菌后，可使用治疗性药剂进行防治，如苯醚甲环唑、嘧菌酯等。加强栽培管理：保持果园通风透光，控制氮肥用量，增施磷钾肥，增强树势，提高柑橘的抗病能力。生物防治：利用柑橘疮痂病的天然拮抗菌，如木霉菌、芽孢杆菌等，进行生物防治。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/531f89fe-0741-4b78-9523-e6ac3629321f.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (127, 18, '柑橘', '黑星病', '是一种由柑橘球座菌侵染所引起的、发生在柑橘上的一种病害。该病主要为害柑橘果实，叶片亦有发生。\n', '春季和夏季', '果园管理不善，如施肥不当、排水不畅、修剪不足等，导致树势衰弱，抗病能力下降。果实接触地面，造成果实受伤，有利于病菌的侵入和繁殖。春季和夏季多雨季节，气温适宜、湿度较高的环境，有利于病菌的繁殖和传播。不同品种的柑橘对黑星病的抗性不同，如果种植的品种易感病，黑星病的发病率就会较高。\n', '清洁田园：及时清除病枝、病叶和病果，并烧毁或深埋，减少病菌来源。加强栽培管理：增施有机肥，注意氮、磷、钾的合理搭配。合理用水，适当修剪，改善通风透光条件，促使植株生长健壮，提高抗病力。对于感病品种和老年树，还要注意缺镁症、流胶病等病害的防治，以免这些病害削弱植株的抗病力。此外，在采收及贮运时，尽量不要损伤果皮，以免在贮运期间增加该病的为害。喷药保护：在植株落花至结果的一个半月内，每隔半个月喷药一次，喷药两三次可预防病菌。修剪时去除过密枝叶。秋末冬初结合修剪，剪除病枝、病叶，并清除地上落叶、落果，同时喷洒波美1～2度石硫合剂。可选用的药品包括0.5∶1∶100倍式波尔多液、40%多·硫悬浮剂600倍液、50%多霉灵可湿性粉剂1500倍液、50%甲基硫菌灵可湿性粉剂500倍液、50%苯菌灵可湿性粉剂1500倍液等。物理防治：在贮藏期认真检查，发现病果及时剔除，控制窖温在1～2℃。化学防治：落花后喷0.5∶1∶100倍式波尔多液、40%多·硫悬浮剂600倍液、50%多霉灵可湿性粉剂1500倍液、50%甲基硫菌灵可湿性粉剂500倍液、50%苯菌灵可湿性粉剂1500倍液。隔15天喷1次，连续3～4次。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/eecbee3a-7dc7-4dc7-ad6c-f7b33b2a4d4c.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (128, 18, '柑橘', '黄龙病', '由亚洲韧皮杆菌所侵染所引起的、发生在柑橘上一种的毁性病害。该病严重影响柑橘产量和品质，甚至造成柑橘树枯死。5月下旬开始发病，8-9月份最严重。春、夏季多雨，秋季干旱，发病重。施肥不足，果园地势低洼，排水不良，树冠郁闭，发病重。\n', '春季和夏季', '带病苗木和接穗。病原体可带病繁殖多年，这是病害传播的主要途径。木虱。柑桔黄龙病的主要传播媒介是木虱，通过有翅蚜在病树和健康树间来回传播。气温。气温高有利于病害发生。降雨。秋季干旱有利于病害发生。管理。果园地势低洼，排水不良，树冠郁闭，偏施氮肥，管理不善，发病重。\n', '培育无病苗木。选择周边3km范围无柑桔果园的地块建立柑桔苗木基地，选择无病砧木和接穗培育健康苗木。促进抽梢整齐。通过肥水管理，促进抽梢整齐，抹除过早或过晚以及零星抽发的新梢,以便用药保护抽发整齐的新梢。防治木虱。利用木虱的趋黄性，在田间悬挂黄板诱杀成虫。黄板应全年悬挂，以每年3～10月为重点诱杀期，及时更换以保持黄板粘性。利用内吸性和触杀性药剂防治木虱。在春、夏、秋梢放梢时喷药防治，以后每隔7天防治一次，直至新梢转绿。抹除夏梢前防治一次，砍除病树前针对病树防治一次。隔离传染。发现果树得病以后，一定要及时连根拔出，而且还要清理环境。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/f4d1004a-3d99-45f5-bd08-92e73ed83b78.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (129, 18, '柑橘', '青霉病', '一种植物病害，主要危害果实，也危害枝叶。该病主要为害贮藏期果实，但也可以为害田间成熟果实。\n', '春季和夏季', '果实受伤的伤口为病原菌入侵提供了条件。温度和湿度：温度在20℃以上，相对湿度在90%以上时，适宜该病菌繁殖。虫害：果实受伤的伤口为病原菌入侵提供了条件。\n', '果实采摘后，要进行防腐处理。防腐处理的方法有很多，可以用40%的甲醛100倍，或用50%的多菌灵500倍进行浸果处理。对贮藏环境进行消毒。贮藏环境要保持清洁卫生，可以用1%的福尔马林或4%的漂白粉进行消毒。栽培措施。在栽培过程中，要注意防治果实蝇等害虫，避免机械损伤，防止病菌侵入。注意贮藏环境的气体成分。柑橘果实贮藏过程中会释放出大量的二氧化碳和乙烯，这些气体会促进柑橘青霉病的发生，因此要注意通风换气。及时处理病果。发现病果要及时摘除，并进行防腐处理。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/f627820c-1ba9-4c21-9bb1-a03e9abdbe37.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (130, 18, '柑橘', '树脂病', '由柑橘间座壳菌侵染所引起的、发生在柑橘上的一种病害。主要危害枝干、果实、叶片等部位\n', '春季和夏季', '冻害、日灼伤、风伤、机械伤等伤口，有利于病菌的侵入。施肥不当：偏施氮肥，树体徒长，造成抗病力下降。排水不良：果园排水不畅，使土壤湿度过高，影响根系的正常生长，削弱树势，加重发病。吉丁虫、天牛等害虫危害严重时，树脂病也会发生严重。\n', '清园。结合修剪，剪除病枝、枯枝和徒长枝，并清理果园中的病果、枯果和落叶落果，集中烧毁或深埋，减少病原菌基数。伤口处理。对各种伤口，应先消毒再包扎，防止病菌侵入。加强栽培管理。合理施肥，控制氮肥用量，增施钾肥和有机肥，增强树势，提高抗病力。同时，应及时排灌，防止果园积水，保持良好的土壤通气性。化学防治。在发病初期，可以使用50%多菌灵可湿性粉剂500倍液、70%甲基托布津可湿性粉剂800倍液或80%代森锰锌可湿性粉剂800倍液进行喷雾，每隔10天喷雾一次，连续喷雾2-3次。同时，在冬季清园时，可以使用石硫合剂或波尔多液进行消毒，以减少病原菌基数。生物防治。可以应用柑橘树脂病专性寄生菌防治柑橘树脂病。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/56688efb-6c72-4040-bae0-30e9a2588fa9.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (131, 18, '柑橘', '炭疽病', '由围小丛壳菌侵染所引起的、发生在柑橘上的一种病害。主要为害叶片、枝梢、花、果实、果梗和苗木，常造成叶枯、梢枯、落花、落果及果实腐烂。\n', '4-5月和7-8月份', '炭疽病菌在温度15℃以上，相对湿度80%以上时，有利于发病。连续阴雨或暴雨转晴后，气温在20-25℃，相对湿度在90%以上时，病害发展迅速，病情严重。成熟果实遇雨，炭疽病极易发生和流行。苗圃和幼龄树园，一般易发病。同一果园中，通风透光差、湿度大的果园发病重。不同品种中，一般早熟品种易发病。\n', '彻底清园。科学施肥，增强树势，提高柑橘的抗病能力。喷药保护。在新叶抽生和幼果期各喷药1次，常用的药剂有：25%使百克乳油1000倍液、80%大生M-45可湿性粉剂800倍液、25%苯醚甲环唑·咪鲜胺乳油1000倍液、25%嘧菌酯悬浮剂1000倍液、25%吡唑醚菌酯乳油1000倍液。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/2a9cd750-228f-4875-8ae3-82d84686ba56.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (132, 23, '白菜', '软腐病', '是细菌性病害。苗期染病始于子叶上，首先产生水浸状病斑，湿度大时产生菌脓，干燥后变为灰白色，引起真叶干枯。有时蔓延到叶茎和蔓上，其上产生裂口和裂纹，传播到果实上，产生水浸状病斑，逐渐扩大为淡褐色病斑，后期病斑易开裂。\n', '9月至10月', '大白菜软腐病是由细菌引起的真菌性病害，主要侵染叶片、茎和根。该病菌在温度3℃-4℃、相对湿度90%-100%的条件下繁殖迅速，白菜最易感病。此外，有伤口的植株比无伤口的植株感病。大白菜在包心期最易感病，尤其是遇到阴雨连绵的天气，病害流行速度很快，特别严重的能引起全株死亡。大白菜在莲座期和包心期对软腐病最为敏感，因此，在这两个时期要重点预防。\n', '做好选种、合理浇水、做好消毒、合理轮作、科学施肥、采用高畦栽培、药剂防治；选用抗病性强的品种；大白菜属于喜水喜肥作物，对水分需求量较大，坚持小水勤浇，防止大水、大肥漫灌，在莲座期后保持土壤见干见湿为宜；发现病株，及时拔除，进行深埋或销毁，同时撒上生石灰、草木灰，或者喷洒杀菌药物消毒。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/6da6f98f-1d57-4fca-b348-e7211b599ad9.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (133, 19, '草莓', '白粉病', '是一种由真菌引起的传染性病害，主要危害草莓的叶片、叶柄、花器、果实和果柄\n', '2、5、10、12月', '草莓白粉病的发病原因主要包括栽培密度过大、管理粗放、水分不合理、氮肥施用过多、品种抗病性差、连作障碍和温湿度不适宜等。\n', '科学施肥，增施腐熟有机肥和磷钾肥，避免偏施氮肥。合理灌水，避免中午浇水，控制土壤湿度。加强通风透光管理，及时摘除老叶、病叶和病果，并烧毁或深埋。在发病初期及时用药防治，可选用腈菌唑、三唑酮、己唑醇、苯醚甲环唑、嘧菌酯等药剂。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/4b6c7d07-7591-41f5-9e4c-a5f40813e0dd.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (134, 20, '玉米', '锈病', '由玉米柄锈菌引起、发生在玉米的病害。主要发生在玉米叶片上，也能够侵染叶鞘、茎秆和苞叶。\n', '7~9月份', '种子携带病菌：种子带菌是锈病发生的初侵染源。玉米收获时，病原菌在病株上越冬，成为下一季的侵染源。连作导致病菌累积：连作使病原菌在田间累积，从而导致锈病的发生。气候条件适宜：锈病发生的适宜温度为20-30℃，相对湿度为85%以上，连阴雨、干旱和昼夜温差大的天气，有利于锈病的流行。\n', '选用抗病品种。清除田间发病的地块，避免在近2年内发病的田块种植玉米。药剂防治。在玉米抽雄前10天，即玉米大喇叭口期，用有效成分含量为20%的粉锈宁乳油每亩100克，或有效成分含量为30%的氧环三唑酮可湿性粉剂每亩50克，或有效成分含量为20%的丙环唑乳油每亩100克，或有效成分含量为12.5%的腈菌唑每亩50克，或有效成分含量为25%的三唑酮每亩100克，或有效成分含量为12.5%的双效灵每亩150毫升，或有效成分含量为40%的禾果利每亩75克，均匀喷施在玉米的叶面上。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/e507ee97-3c2c-41c6-a597-4dcf27f97a7a.jpg', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (135, 21, '哈密瓜', '角斑病', '是细菌性病害。苗期染病始于子叶上，首先产生水浸状病斑，湿度大时产生菌脓，干燥后变为灰白色，引起真叶干枯。有时蔓延到叶茎和蔓上，其上产生裂口和裂纹，传播到果实上，产生水浸状病斑，逐渐扩大为淡褐色病斑，后期病斑易开裂。\n', '春、夏、秋', '种子携带病菌：种子带菌是锈病发生的初侵染源。玉米收获时，病原菌在病株上越冬，成为下一季的侵染源。连作导致病菌累积：连作使病原菌在田间累积，从而导致锈病的发生。气候条件适宜：锈病发生的适宜温度为20-30℃，相对湿度为85%以上，连阴雨、干旱和昼夜温差大的天气，有利于锈病的流行。伤口感染：哈密瓜在生长过程中，如遭受病虫害、旱、寒、虫、机械损伤等，导致伤口过多，易感染角斑病。\n', '农业防治：第一，选择地势平坦、排水良好的地方种植哈密瓜，做到深耕细作；第二，加强肥水管理，施肥要氮磷钾复合肥，对哈密瓜进行叶面追肥，增强哈密瓜的抗病能力；第三，对土地进行轮作，能够有效控制土壤中的病菌；第四，对种子进行消毒处理，避免种子携带病菌。化学防治：在未发病时，在哈密瓜植株上喷洒1%波尔多液或77%可杀得500倍稀释液，或600倍稀释液进行预防。在发病后，使用农用链霉素或新植霉素4000倍稀释液、琥胶肥酸铜1000倍稀释液、绿享800倍稀释液、消菌灵1000倍稀释液、10%抗菌剂401醋酸溶液1000倍稀释液、72%农用链霉素可溶性粉剂4000倍稀释液等药物进行喷洒治疗。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/ccb83a8c-b161-4b12-839e-ddd46452e7d2.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (136, 26, '火龙果', '软腐病', '多种细菌引起的病害。主要危害火龙果的茎和叶。细菌从伤口入侵，引起组织腐烂，并释放出臭味。\n', '1月下旬至3月上旬', '伤口感染：如叶、茎、花和果实出现伤口，病原细菌从伤口入侵，引起组织腐烂。病原细菌在病组织和病残体上越冬：细菌可以在土壤里存活多年，从伤口、叶、茎和花蕾的皮孔入侵，从根部伤口入侵时，一般从上年日灼伤或虫伤处入侵。高温高湿：有利于该病的发生和发展，尤其阴雨天久晴不雨，利于软腐病的发展。虫害：如红蜘蛛、锈蜘蛛、白蚂蚁等危害火龙果的枝条和树皮，造成伤口，有利于病菌的侵入。施肥不足和偏施氮肥：破坏了土壤团粒结构，造成土壤盐分偏高，对根部造成伤害，加重软腐病的发生。连作：同一块地上种植火龙果，会加重软腐病的发生。\n', '培育无病苗木：培育无病苗木，选择无病植株作为繁殖材料。农业防治：加强果园管理，提高树体抗病能力；及时清除病残体和落叶，集中烧毁或深埋；控制灌水，避免漫灌和长时间浸泡，保持土壤通气性；施用腐熟有机肥，避免偏施氮肥。药剂防治：及时对火龙果进行喷药保护和治疗，常用药剂有农用链霉素、春雷霉素、中生菌素、噻唑锌、氢氧化铜等。在药剂干后再喷清水洗去茎表面的药液，避免产生药害。\n\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/5adf3a8e-85ef-4b20-99f9-fca193c0c829.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (137, 25, '梨', '轮纹病', '是一种由真菌引起的梨树病害，主要危害枝干和果实，也危害叶片。该病主要发生在梨产区，当气温在20℃以上，相对湿度在75%以上，降雨量达10毫米或连续下雨3-4天，病害传播快。肥料不足、树势弱、虫害重时，梨轮纹病发病重。\n', '7-8月', '是由一种梨轮纹韧皮部杆菌侵染而引起的病害。这种病菌在枝干上长期存活，在多雨年份和生长季节，特别是在连续降雨和果实糖分转化期，有利于病菌迅速繁殖和病害传播。因此，树冠郁闭、湿度大、通风透光不良的梨园，以及发病后未及时防治的梨园，往往发病较重。该病的发生与气候和品种有关。当气温在20℃以上，相对湿度在75%以上，降雨量达10毫米或连续降雨3-4天时，病害传播快，病情加重。肥料不足、树势弱、虫害重时，梨轮纹病发病重。\n', '梨轮纹病的防治方法主要以农业防治和化学防治为主。首先，进行检疫，防止病害传入。其次，在秋末冬初清除病源，加强土肥水管理；采下的果实在温度0-5℃的条件下贮藏，可基本控制梨轮纹病的扩展。最后再结合化学药剂进行防治。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/b2ab5313-7e73-4bfe-86a3-8818000ed4bc.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (138, 24, '荔枝', '煤烟病', '荔枝煤烟病是由小煤炱菌、煤炱菌等10余种真菌引起的、发生在荔枝的病害。主要危害荔枝叶片、枝条和果实。发病初期在病部表面产生一层暗褐色小霉斑，以后增厚成绒状的黑色或暗褐色霉层，呈煤烟状，后期于霉层上散生黑色小点粒或刚毛状长形分生孢子器突起物。\n', '5-6月', '病原为半知菌亚门小煤炱属的真菌，以菌丝体、分生孢子器在病部或病叶上越冬，翌年孢子飞散，借风雨传播。通过蚜虫、木虱、粉虱等的分泌物而繁殖蔓延，湿度大时行光合作用，营养来源充足，有多个新生的短距扩展，严重时菌层形成如麻的煤烟状物，有时许多病株的表面互相连成一片。\n', '加强果园管理，科学施肥，增强树势，提高树体抗病力；合理修剪，保持良好的通风透光条件。清除病原。结合修剪，剪除病枝、病叶，清楚园内枯枝落叶，并集中烧毁或深埋。防治害虫。及时防治介壳虫、蚜虫、粉虱等害虫，减少发病因素。药剂防治。在发病初期，及时喷药防治，每隔7-10天喷1次，连续喷2-3次。药剂可选用石硫合剂、多菌灵、甲基硫菌灵、代森锌等。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/210a2ce4-3b0e-4e7d-95bf-d4ac76fbd23b.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (139, 22, '香蕉', '冠腐病', '是由半裸镰刀菌等四种镰刀菌（Fusarium semitectum）引起的真菌性植物病仅次于炭该病主要引起蕉指脱落，轴腐和果腐\"。\n', '春夏季出现症状，8-9月进入盛发期', '在高温高湿条件下最易发生。病害的严重程度与季节、天气、土壤酸碱度、土壤含水量以及植株的生育状态有关。在夏季，温度高、湿度大，有利于半裸镰刀菌等香蕉冠腐病病原菌的生长和繁殖，因此该病在这个季节最易发生和流行。土壤酸度高和含有大量游离酸时，也有利于冠腐病的发生。机械伤口是镰刀菌侵染的重要途径，土壤中的专性寄生性真菌和一些害虫（如象鼻虫）也可导致该病的发生\n', '农业防治。农业防治方法主要通过选用抗病性强的品种、调控土壤酸碱度和避免机械伤口等手段来控制香蕉冠腐病的发生和流行。物理防治。物理防治方法主要包括日光暴晒、黑光灯诱杀、建造障壁、高压等方法，可以有效地杀死病虫害。生物防治。生物防治是通过利用捕食性天敌、寄生性天敌、病原微生物等天敌，来控制香蕉冠腐病的发生和流行。化学防治。化学防治方法主要通过喷洒农药来控制香蕉冠腐病的发生和流行。在选择农药时，应选择杀虫剂、杀菌剂等有效的药剂，并根据具体情况选择不同的药剂进行喷施。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/f53ad4f2-512e-487a-90a6-7838d0251a01.png', 0, '2023-06-11 13:01:35');
INSERT INTO `data_info` VALUES (140, 23, '白菜', '霉斑病', '白菜霉斑病是由无性菌灰色链霉菌（Alternaria brassicae）引起的一种病害。该病主要表现为叶片上出现灰褐色斑点，中央凹陷，边缘呈不规则形状，随着病情加重，斑点变大并融合，最终导致叶片枯萎。', '春季和秋季', '温度湿度适宜：气温15℃左右，相对湿度在75%以上，有利于病菌生长繁殖。植物抗病力弱：植株长势不良、缺乏养分、叶面有伤口等都会削弱植物的抗病能力，易于感染该病菌。病菌过冬：冬季病菌可以通过形态转变为假性休眠体，在土壤中过冬，下一年再度侵染植株。', '选择病害抗性强的品种：选择对白菜霉斑病抗性强的品种进行种植，可有效降低病害发生率。加强田间管理：及时清除田间杂草、枯叶及残留物等，保持田间通风透气，利于减少病菌的繁殖和传播。合理施肥：保证植株养分供应充足，有利于植株健壮，提高其抗病能力。使用化学药剂：如出现严重病情时，可使用适量的化学药剂进行防治，但要注意按照药剂使用说明进行操作，避免药害。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/689ba290-c727-4b2b-9bce-97dcfbef68f1.jpg', 0, '2023-06-20 15:34:31');
INSERT INTO `data_info` VALUES (148, 20, '玉米', '大叶斑病', '大叶斑病：又称玉米灰斑病，由真菌波先孢属（引起。初期在玉米叶片上出现褐色小斑点，后逐渐扩散，形成灰白色圆形或不规则形状的病斑，病斑边缘呈暗紫色，中央干枯变黑，严重时病斑可覆盖整个叶片。同时，植株生长势弱，影响产量。', '夏季到秋季', '大叶斑病的发病原因：主要是由真菌波先孢属感染引起的。该菌在玉米上越冬，当气温在20-30℃左右，空气湿度较高时，病菌侵入玉米叶片内部，并在叶片上形成灰白色病斑，从而引起病害的发生。', '选择抗病性强的品种：在种植玉米的时候要尽量选用抗病性好的品种，这样可以提高植株的抵抗力，降低患病的风险。加强田间管理：及时清理田间的玉米杂草、秸秆等残留物，减少病原体的藏匿和繁殖。避免玉米密植，保持适当的通风透气，避免长时间高湿度环境的形成。合理施肥：注意适量施肥，避免过度施肥或缺乏养分，维持良好的土壤环境，提高植株的抵抗力。使用化学药剂：可以使用有效的化学药剂进行防治，但必须按照标准施用，避免对环境带来负面影响。另外，为了防止病菌产生耐药性，应轮换使用不同类型的药剂。生物防治：可以用一些天然的生物制剂进行防治，如枯草芽孢杆菌、木霉菌等', 'https://etrees.oss-cn-shanghai.aliyuncs.com/e2b88647-dbd2-48b9-af79-2546be750b22.jpg', 0, '2023-06-28 18:26:37');
INSERT INTO `data_info` VALUES (149, 11, '番茄', '黄叶病', '番茄黄叶病会导致植物产生黄化症状、植株生长迟缓、果实减产等问题，严重时可能导致植物死亡。', '夏秋季', '该病的发病原因主要是由白粉虱（Bemisia tabaci）传播的病毒引起。白粉虱作为TYLCV的主要传播媒介，在吸食感染了该病毒的植物汁液后，会将病毒带入其体内，然后再通过吸食未感染植物的汁液将病毒传播给宿主植物。', '加强田间管理：及时发现并清除病虫害、采取消毒措施、定期进行田间巡视，防止病毒的传播和扩散。生物防治：利用对该病毒具有拮抗作用的微生物，如青霉素、金黄色葡萄球菌等进行生物防治，控制病原体的扩散。化学防治：通过喷洒杀虫剂、杀菌剂等化学药剂控制病毒的传播和扩散，达到防治效果。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/1563a6e2-43bb-46ce-a951-8ea008274825.JPG', 0, '2023-06-21 17:08:04');
INSERT INTO `data_info` VALUES (151, 28, '菠萝', '凋萎病', '菠萝凋萎病是由菠萝凋萎病病毒引起的、发生在菠萝的病害', '11月至翌年1-2月', '早期的观点认为，菠萝凋萎病是由菠萝粉蚧取食所致，后来认为可能是由菠萝粉蚧分泌的毒素引起的，再后来普遍认为是由菠萝凋萎病病毒所致。美国夏威夷从菠萝凋萎病病株中分离到3种菠萝凋萎病病毒，其中PMWaV-2为致病病毒；菠萝凋萎病病毒为+dsRNA结构，长杆状，被归于Closteroviridae科、Ampelovirus属。', '农业防治。菠萝凋萎病菌丝体和子实体在病残株上越冬，成为主要初侵染源，因此，在菠萝收获后，要及时清理果园，烧毁病株残体。建立无病留种田，培育无病壮苗。高畦种植，避免果园积水和水土流失，对高岭土和黏重土应增施有机肥料，改良土壤通气性，促进根系生长，及时挖除病株并烧毁。药剂防治。发现病株，可及时选用50%马拉硫磷乳油800倍液，或80%敌敌畏乳油1000倍液浸种苗5-10分钟消毒，倒置晾干后种植。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/1e10bc9b-acbb-4b55-96b6-b03c6b1e4f4a.jpg', 0, '2023-06-21 17:13:10');
INSERT INTO `data_info` VALUES (152, 28, '菠萝', '粉蚧凋萎病', '菠萝粉蚧凋萎病是由菠萝凋萎病病毒引起的、发生在菠萝的病害', '11月至翌年1-2月', '早期的观点认为，菠萝凋萎病是由菠萝粉蚧取食所致，后来认为可能是由菠萝粉蚧分泌的毒素引起的，再后来普遍认为是由菠萝凋萎病病毒所致。美国夏威夷从菠萝凋萎病病株中分离到3种菠萝凋萎病病毒，其中PMWaV-2为致病病毒；菠萝凋萎病病毒为+dsRNA结构，长杆状，被归于Closteroviridae科、Ampelovirus属。', '农业防治。菠萝凋萎病菌丝体和子实体在病残株上越冬，成为主要初侵染源，因此，在菠萝收获后，要及时清理果园，烧毁病株残体。建立无病留种田，培育无病壮苗。高畦种植，避免果园积水和水土流失，对高岭土和黏重土应增施有机肥料，改良土壤通气性，促进根系生长，及时挖除病株并烧毁。\n药剂防治。发现病株，可及时选用50%马拉硫磷乳油800倍液，或80%敌敌畏乳油1000倍液浸种苗5-10分钟消毒，倒置晾干后种植。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/47609582-e73b-4768-9e54-bb2787905b21.jpg', 0, '2023-06-21 17:14:25');
INSERT INTO `data_info` VALUES (153, 28, '菠萝', '心腐病', '菠萝心腐病是由几种疫霉菌引起的、发生在菠萝的病害。主要侵害茎及叶片的幼嫩部分，造成植株心部奶酪状软腐，心叶极易拔起。', '多雨季节', '长期堆放：种苗长期集中堆放在一起，内部菠萝苗呼吸产生热量不能及时散失，积累的热量形成高温，加之有高湿的环境，导致菠萝种苗受影响，感染病菌。积水：移栽后菠萝苗栽植环境中有积水情况，易导致菠萝苗根部缺氧、无氧呼吸产生有毒物质，根系受损,且易感染病菌，从而发生心腐病。晒苗时间过短：晒苗一般是指将种苗倒置,放在阳光下晾晒，通过阳光中的紫外线杀死菠萝根部的病菌。晒苗时间过短，杀菌不充分,易引起苗心腐病的发生。', '农业防治：种植前，挑选健康的菠萝苗；种植地选择在通风干燥的地方，排水系统要做好，避免积水；菠萝苗种植前，可以用多菌灵溶液浸泡根系，晾干后再进行种植；定期巡查菠萝田，发现有病株及时清理，防止感染其他菠萝。\n药剂防治：菠萝心腐病发生时，可以使用农药，例如甲霜灵、甲霜灵·锰锌、杀毒矾、百菌清等溶液进行灌根，此外，在菠萝田中心病株区域应撒施生石灰，防止病菌蔓延。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/988d1451-cc28-4d47-88c3-3252bbcd1558.jpg', 0, '2023-06-21 17:15:25');
INSERT INTO `data_info` VALUES (154, 29, '橙子', '黄龙病溃疡病', '橙子黄龙病溃疡病别名为黄龙病、黄梢病，是由韧黑杆菌引起的一种非侵染性病害', '5月', '苗木、接穗及果实带病传播。柑桔木虱传播。工具不带消毒水传播病树与健树混栽传播。适生环境有利于病菌的繁衍加速了病情的发展。', '建立无病苗木基地，培育无病壮苗。彻底防治柑桔木虱。清除病树，减少病源。经常喷药防治柑桔木虱，使之起到预防作用。使用四环素或青霉素注射病树树干，有一定治疗效果。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/2176a610-3bbe-459b-a412-6815ebe86701.jpg', 0, '2023-06-21 17:16:39');
INSERT INTO `data_info` VALUES (155, 29, '橙子', '橙子沙皮病', '橙子沙皮病又称树脂病，是一种危害新梢、嫩叶和幼果的病害。', '4～6月和8～9月', '偏失氮肥、缺钙、硅元素树易发病。树势弱易发病， 土壤酸性强、粘重、砂化等原因，不利于果树生长造成树势弱。通风条件差、长期湿度大、树脂病菌的活跃度较高。树体机械性损伤和冻害造成大量的伤口易发病。', '加强栽培管理，合理施肥，增强树势，提高树体抗病能力。及时剪除枯枝、病枝、病果等，集中带出园外处理，减少病原菌数量。做好果园清园工作，清除落叶落果，剪除病枝叶，减少病原菌数量，发病前或发病初用靓果安150-200倍+有机硅喷雾靓果安150-200倍喷雾，严重时配合大蒜油1000-1500倍喷雾。果实套袋，减少果实与病菌接触的机会，错过7月沙皮上果高峰期套袋。调节果园湿度、改善果园环境、控制梢期、改善枝叶结构，通风透气；发病前或发病初用靓果安150-200倍+有机硅喷雾靓果安150-200倍喷雾。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/0b14e97a-6410-43a1-98b3-497480416e86.jpg', 0, '2023-06-21 17:17:32');
INSERT INTO `data_info` VALUES (156, 29, '橙子', '炭疽病', '橙子炭疽病，是一种真菌性病害，属于弱寄生菌', '5月7月 9月11月', '脐橙炭疽病为潜伏感染性病害，其病原菌是一种弱寄生菌，就像人类的乙肝病毒一样，健康正常人不易发病。病原病原为真菌。病菌在树上被害部越冬，春天通过风雨、昆虫传到树上，易侵入。当树势强壮，则不发生病变；当树体生长衰弱时，才出现病变。因此在果树遭受冻害及水、旱害、缺肥或害虫为害等不良因素的影响时，易诱发此病。', '炭疽病病菌是一种弱性寄生菌，只有在树体生长衰弱的情况下，才能侵人危害。因此，加强栽培管理，培育强壮树势是防治炭疽病的根本途径。\n清除园内枯枝落叶，集中烧毁，减少病源。在脐橙实际生长过程中，应关注脐橙的生长情况，依据其实际情况,及时浇水施肥,保证树势健壮,进而增强植株抗病能力。药剂防治。在春、夏、秋梢嫩叶期，特别是在幼果期和8-9月份果实成长期，每隔15-20天，喷药1-2次。药剂可选50%甲基硫菌灵可湿性粉剂500-700倍液，或50%胂·锌·福美双可湿性粉剂500-700倍液，或50%多菌灵可湿性粉剂800-1000倍液。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/7b5d5dcf-103c-4674-8de6-c6a36deeb2a2.jpg', 0, '2023-06-21 17:18:28');
INSERT INTO `data_info` VALUES (157, 30, '芒果', '白粉病', '芒果白粉病是由芒果粉孢霉引起的、发生在芒果的病害。', '2月～4月', '温度条件是影响芒果白粉病流行的主要因素，月平均气温为21—22℃时，最适于芒果白粉病的发生。湿度的影响较小，70%左右的相对湿度对芒果白粉病的发生较有利，但干旱地区同样发病严重，过多降雨反而抑制发病。\n施氮肥过多，枝叶组织柔嫩，易感芒果白粉病。', '农业防治。加强果园管理，合理密植，注意通风透光，创造不利于芒果白粉病发生的条件；清理果园，发现病枝、病叶、病果等，应及时清除；注意氮、磷、钾肥的合理搭配，避免过施氮肥，造成植株徒长，提早抽水。药剂防治。在开花初期和谢花达70%时，喷施靓果安150-200倍+大蒜油1000倍，萌芽用工，减少白粉病基数；谢花80%后幼果期用靓果安150-200倍+大蒜油1000倍+链霉素300倍，防治白粉病和减少细菌性病害。靓果安中含有天然活性物质多酚类108种，芽孢杆菌T33、T66以及97种中药微量元素。具有杀菌、渗透性强，能快速进入植物细胞，抑制病毒复制，对白粉病、霜霉病、疫病等病毒病害有特效。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/025660e3-f5c0-4b15-9215-54b2d26f7900.jpg', 0, '2023-06-21 17:19:52');
INSERT INTO `data_info` VALUES (158, 30, '芒果', '疮痂病', '芒果疮痂病是由芒果痂圆孢菌引起的、发生在芒果的病害。', '5,6,7月和12,1月', '气候因素：气候条件是造成芒果患上芒果疮痂病的重要原因。芒果疮痂病的发病比较密集的时候一般都是在高温多雨的比较潮湿的时节。在环境温度为二十摄氏度到二十四摄氏度之间的时候，芒果疮痂病是最容易发作的。这时因为已经满足了温度条件，所以相应的当湿度上再具备阴雨连绵或者是雾大露重的情况时，就会加快芒果疮痂病病菌的传播，使芒果染病的可能性大大增加。品种因素：受到芒果品种不同的影响，芒果具体的抗病能力和发病情况也会不同。一般来说，厚皮的芒果以及青芒类的比较容易染上芒果疮痂病，而桂香芒的则是抗病能力比较强，也不太容易受到芒果疮痂病的干扰的。', '实施检疫，病区苗木严禁外运。注意田间卫生，收集病枝残叶，及时烧毁。及时喷药保梢保果，苗圃和幼年树以保梢为主，结果成年树以保果为主，掌握各次抽梢期以及果实开始膨大至采果前15—20天止，交替连续喷药保护。常用药剂有0.5：（0.5-1）：100的波尔多液，50%多菌灵可湿性粉剂800-1000倍液，70%托布津可湿性粉剂800-1000倍液等。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/68c5374c-7678-4822-a2ab-07786c5b71d7.jpg', 0, '2023-06-21 17:20:41');
INSERT INTO `data_info` VALUES (159, 30, '芒果', '蒂腐病', '芒果蒂腐病主要是由芒果拟茎点霉引起的、发生在芒果的病害。', '夏季', '病菌的侵入途径是在花期侵入，幼果内潜伏，在果实后熟阶段表现症状。病菌也可以从采果时的伤口及剪口处侵入，这是病原菌最主要的侵入途径。\n分生孢子通过雨水和气流传播，而在果实采后的运输期则主要是靠病果与健果相互接触，由菌丝体传播。', '加强果园管理，注意调整园内的排水系统，清理果园，合理修剪，防除杂草等，减少病菌的越冬基数及初次侵染来源。合理施药，冬季清园修剪后喷1-2次护树大将军消毒杀菌，抑制病菌复制，适时施药，从花穗期至果实成熟前喷药2-3 次壮果蒂灵+新高脂膜可激活植物生态生长正能量，拓宽植物导管路径，提升植物吸水吸肥力度，提升果实产量和质量，降低落果率，减少裂果、僵果、畸形果发生率。介素，抑制残余病毒复制，促进植物正能量生态生长。整形修剪:要疏除内膛枝、重叠枝、弱枝、病虫枝,改善芒果生长需要的环境条件。清园卫生:及时清除枯枝病叶及地面上的枯枝、落果。药剂防治:在芒果新梢期、花穗期及幼果期要喷药防治。剪果:在靠近蒂基部0.3厘米处把果剪下。洗果:用2%~3%漂白粉水溶液或流水洗去果面杂质。选果:剔除病、虫、伤、劣果。防腐处理:采用29℃的5%施保功可湿性粉剂1000倍液处理2分钟,或用52℃45%特克多胶悬剂1000倍处理6分钟。分级包装:按级别分佣白纸单果包装。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/9abfd237-0122-4a32-971d-0c24c2ddb707.jpg', 0, '2023-06-21 17:21:32');
INSERT INTO `data_info` VALUES (160, 31, '枇杷', '腐烂病', '枇杷腐烂病，别名枇杷烂皮病，是枇杷生产上的主要病害之一，由真菌引起。', '冬', '枇杷腐烂病病菌主要在病树干和其他病残体中越冬，通过雨水进行传播，从果树伤口侵入发病。枇杷树生长健壮，抗病能力强，病菌可潜伏相当长的时间不发病，而树势弱、抗病力差的树，发病迅速，很快引起树皮腐烂。腐烂病在早春气温持续偏高、雨量多、湿度大，枇杷腐烂病的病菌产生新的分生孢子器提早，造成腐烂病流行。另外，防治不当也会造成枇杷腐烂病的发生。如果干腐病已经发生时，选晴天先用工具将病部的树皮切割，深达木质部，或者直接用工具将病部刮除，露出生长健壮部位，然后用淇林仕勋稀释50-100倍液用毛刷对病部进行涂抹。', '加强果园土、肥、水管理，增强树势，提高树体抗病能力。防止冻害、日灼和机械伤等，减少病菌侵染的伤口，对机械伤口要用蜡或涂胶泥密封。彻底挖除病株和剪除病枝，及时将挖出的病株和病枝运出园外，集中烧毁或深埋。在刮除腐烂病斑深划刻标记后，用50%多菌灵可湿性粉剂100～200倍液或70%托布津可湿性粉剂100～200倍液或治腐灵100～200倍液或3%腐必清乳剂100倍液等药剂涂抹病斑，在刮除病组织后涂抹药剂效果更佳。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/2468d9ef-4acc-4b19-9a22-03ab22e16eeb.jpg', 0, '2023-06-21 17:25:16');
INSERT INTO `data_info` VALUES (161, 31, '枇杷', '苹果密蛎蚧', '枇杷苹果密蛎蚧Mytilaspis canchiformioides (Borchsenius)是属于同翅目盾蚧科的一种昆虫，主要寄生在枇杷的枝条和叶片上。', '7月8月11月12月', '虫害原因：由于温湿度适宜，大面积观察发生量偏重。温度原因：温度越高，苹果密蛎蚧的繁殖速度越快。湿度原因：空气越干燥，苹果密蛎蚧的繁殖速度越快。', '人工防治：应掌握在若虫盛发期喷药防治，间隔期视发生情况而定；\n药剂防治：可选用40%速扑杀800~1200倍液、95%蚧螨灵100倍液、35%克蚧灵1500倍液或35%卵虫净500倍液等。另外，改善果园通风透光条件 ，结合修剪 ， 剔除受害严重的枝条和果实，集中烧毁 ，以减少越冬虫口基数。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/cf63ebe4-bbf9-4af9-98d2-9e69429557b6.jpg', 0, '2023-06-21 17:26:29');
INSERT INTO `data_info` VALUES (162, 31, '枇杷', '炭疽病', '枇杷炭疽病是一种危害幼苗，致使叶片大量脱落并形成叶斑的植物病，主要由炭疽菌引起。', '6-9月', '排水不良、氮肥过量、枝叶密封、雨季或风、冰雹，易感染炭疽病。\n园地湿度越大、氮肥过多、荫蔽通风、透光差、 虫害较多的枇杷园均促使此病害的发生。天气和发病情况，每半月喷洒一次，喷洒1-2次，常用药物有波尔多液体、多菌灵、甲基托布津、百菌清。', '做好清园工作，剪除病枝、病果，清扫落叶烂果，集中销毁。\n加强管理，做好肥水供应，及时防治食果害虫。在采收和贮运过程中应尽量避免机械伤。喷药保护，抽梢期、花期和幼果期是炭疽病侵染的主要时期，要进行喷药保护。在冬春季,从枇杷果实硬核时起,必须每10~15天面喷洒一次1:1:200波尔多液、40%灵福WP1:1000倍液、53.8%可杀得2000型WP1:800倍液、80%大生M-45WP800倍液或75%百菌清WP600倍液等药剂进行防治。果实套袋前喷洒一次800倍50%扑海因可湿性粉剂水溶液,果实套袋后就不容易感染炭疽病,落果烂果就明显减少。在枇杷果实膨大期间,磷、钾、镁、钙供应不足时,果实就很容易感染炭疽病,如果能在上述杀菌剂中加入0.2%磷酸二氢钾、0.3%硝酸钙、0.1%硫酸镁混合液,或800倍星朋磷钾1号、800倍星朋钙镁1号混合液同喷,防病效果更佳,还能加快病果恢复正常生长,提高产量和改善品质。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/d96e2ed3-7076-4494-886e-7003d015597b.jpg', 0, '2023-06-21 17:28:42');
INSERT INTO `data_info` VALUES (163, 32, '柿子', '角斑病', '柿子角斑病是我国柿树生产中的一种主要病害，主要危害柿叶，也能危害柿蒂', '5-8月', '子角斑病是由一种真菌（称为Discula destructiva）引起的病害。这种真菌会在柿子树的树皮、果实和叶子上形成黑褐色圆形斑点，并最终导致叶片枯萎和果实腐烂。这种病害的形成原因通常与环境因素有关，包括高湿度、降雨量和潮湿的天气条件。感染通常发生在春季或夏季，当温暖潮湿的气候条件下，柿子树受到了伤害，如虫害、机械伤害或太阳灼伤时，更容易受到病菌的攻击。此外，不适当的栽培措施和缺乏足够的养分也可能增加柿子角斑病的风险。', '清除挂在树上的病蒂：这是减少病菌来源的主要措施，只要彻底清除柿蒂，即可避免此病成灾。喷药保护：喷药预防的关键时期在6月下旬至7月下旬，即落花后20-30天，过早过晚都不好。药剂可用1:3至5:300-600的波尔多液，65%的代森锌可湿性粉剂500-600倍液，喷1-2次，可有效地控制病害发生。\n避免柿树与君迁子混栽：君迁子的蒂特别多，为避免其带病侵染柿树，应尽量避免柿树与君迁子混栽。加强栽培管理：增施有机肥料，提高树体抗病力，降低果园湿度，创造不利于病菌繁殖的条件，从而达到控制病害的目的。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/3c844c6c-c93e-439d-81f5-3294e71b0ada.jpg', 0, '2023-06-21 17:29:39');
INSERT INTO `data_info` VALUES (164, 32, '柿子', '炭疽病', '柿子炭疽病，主要危害果实，也侵害新梢和叶', '6月至7月', '养护管理不当，或者生长环境过于闷热。叶片一般很少发病，在发病的初期，果实会出现褐色的斑点，在后期的时候就会逐渐的扩大，呈现出圆形，而且叶柄也会变黄，甚至变黑。', '防治方法：改善果园通透性，防止园内郁闭。平衡施肥，促进树体健壮。多施有机肥，配施磷钾肥，少施氮肥。清洁果园，彻底清除菌源。冬季结合修剪，彻底清园，剪除病枝梢，摘除病僵果；生长季及时剪除病梢、摘除病果，对清除的病枝梢、果、叶集中烧毁或深埋，减少再侵染菌源。萌芽前喷施波美5度石硫合剂。完善水利建设，确保排灌畅通。雨水过多，排水不畅，加重病害发生，因此耕种帮建议雨季到来之前，应完善水利配套，保证雨止田干 ,及时降湿。化学防治。6月中旬至7月中旬喷施两遍1:5:400～500倍波尔多液，为避免后期影响果实外观光泽,7月下旬开始用70%甲基托布津800～ 1000倍等药剂进行防治(混加0.2%～0.5%尿素避免产生药害)。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/fa578ebb-79fd-4226-b2da-04a1a4caa817.jpg', 0, '2023-06-21 17:30:46');
INSERT INTO `data_info` VALUES (165, 32, '柿子', '圆斑病', '柿子圆斑病是由柿子圆斑病菌引起的一种柿子病害。', '6-8月', '柿子圆斑病是由一种真菌（Cercospora kaki）引起的，在温暖潮湿的条件下，该真菌会感染柿子树产生病害。感染通常发生在春季或夏季，当气温和湿度达到一定水平时，真菌会在树叶上形成圆形浅黄色或灰色斑点。柿子圆斑病的发生还与树木的健康状况有关。如果植物处于应激状态（例如缺少养分、过度灌溉或受到虫害等伤害），则其抵抗力将降低，易受到病原体的侵袭。', '保持树木健康：注意定期施肥、控制适当灌溉量和确保土壤通风性；清除树下落叶：降低病原体在叶片上的感染机会；剪枝处理：及时修剪和清除树枝或枯叶，以减少病原体在树上的积累；使用杀菌剂：可选用铜剂、氢氧化钙等杀真菌剂对柿子树进行喷洒。在发现初期病变时，喷洒杀菌剂效果更佳；使用生物制剂：可选用含有抗病菌株的生物制剂来控制柿子圆斑病病害。具体使用方法可参考产品说明书。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/91039553-637d-495c-9a27-44730e11c96f.jpg', 0, '2023-06-21 17:31:38');
INSERT INTO `data_info` VALUES (166, 33, '西瓜', '猝倒病', '西瓜猝倒病是西瓜苗期主要病害之一，发病初期在幼苗近地面处的茎基部或根茎部生出黄色至黄褐色水渍状缢缩病斑，致幼苗猝倒，一拔即断。', '早春', '苗床通风不良，光照不足，湿度偏大，低温，高湿，土壤中含有机质多，施用未腐熟的粪肥等，均有利于该病的发生。土壤温度10-15℃，湿度大或夜温很低、白天光照不足时得于猝倒病发生。', '做好种子处理，播种前将种子用新高脂膜拌种能驱避地下病虫，隔离病毒感染，不影响萌发吸胀功能，加强呼吸强度，提高种子发芽率。加强苗床管理，搞好温湿度调控，特别注意湿度的控制，适量浇水，加强通风排湿。药剂防治：发现病株后及时用药水喷雾和灌根，可用72.2%普力克水剂800倍液、69%安克锰锌可湿性粉剂1000倍液、64%杀毒矾可湿性粉剂500倍液、72%克露可湿性粉剂800倍液、58%甲霜灵·代森锰锌可湿性粉剂400倍液、10%双效灵水剂300倍液、40%乙磷铝悬浮剂300倍液、50%甲霜铜可湿性粉剂600倍液、99%精品瑞毒霉可湿性粉剂800倍液、绿亨3号950倍液等药剂，轮换使用，每隔7-10天1次，连续防治2-3次。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/a704c4da-868f-431a-9b5a-1995eb17ef94.jpg', 0, '2023-06-21 17:35:03');
INSERT INTO `data_info` VALUES (167, 33, '西瓜', '蔓枯病', '西瓜蔓枯病俗称蔓割病，是由瓜类黑腐球壳菌侵染所引起的、发生在西瓜上的病害。', '春秋两季', '病菌主要以分生孢子器或子囊壳随病残体在土壤中越冬，也可附着在棚室架材上越冬，种子能带菌传病。借助风雨传播，从植株伤口、气孔或水孔侵入。土壤水分多，茎部经常接触水，田间相对湿度大，都容易引起发病。病菌喜温暖和高湿条件，最高35℃、最低5℃、适温20-24℃相对湿度85%以上，土壤湿度大时易发病。茎基部发病与土壤水分有关，土壤湿度大或田间积水，易发病。保护地通风不良、种植过密、连作、植株脱肥、长势弱、光照不足、空气湿度高或浇水过多、氮肥过量或肥料不足，均能加重病情。', '实行轮作，采用抗病砧木育苗。采用垄作或高畦深沟方式种植，合理密植，注意通风采光，定植前清除田间杂草，加强肥料水管理，防止干旱，雨后及时排水。清洁田园，在病害发生后及时拔除病株，全面细致地中耕除草，并以此减少寄生场所和消灭部分菌源和虫源。药剂防治：加强栽培管理，在西瓜生长期间及时防治害虫避免虫伤。在药剂防时用75%百菌清可湿性粉剂600倍液或70%代森锰锌可湿性粉剂500倍液对水喷雾防治炭疽病。蔓枯病可以用25%嘧菌酯悬浮剂1500倍液或80%大生M-45可湿性粉剂600倍液喷雾防治。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/fa663fe3-4ab5-4dfb-8399-462690cfb8f2.jpg', 0, '2023-06-21 17:35:53');
INSERT INTO `data_info` VALUES (168, 33, '西瓜', '疫病', '西瓜疫病又称疫霉病，俗称死秧、卡脖子，是由德雷疫霉和辣椒疫霉侵染所引起的、发生在西瓜上的病害。', '春季4-7月', '连作地、地势低洼、排水不良的田块发病较早较重。种植过密，通风透光差，氮肥使用过多或施用未腐熟的有机肥，发病重。受高温高湿的气候影响发病重。历年西瓜疫病发病早、发病重的田块。地下害虫危害严重的田块。串灌、漫灌、农事操作容易引起传播。', '轮作：选用抗病品种，轮作3年以上。嫁接防病：利用黑籽南瓜、西葫芦、瓠瓜作砧木。加强肥水管理：施用充分腐熟的农家肥，不要施用含有西瓜秧蔓、叶片、瓜皮的圈肥。育苗时保证充足的磷钾肥供应，以培育壮苗。采用基质栽培，应用膜下滴灌技术或暗灌技术，科学灌水。冬春季灌水过多，及时整枝打杈，摘除病叶，防止叶蔓生长过密，行间通风不良。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/b9209046-5008-4dcf-a5ac-5340478366e2.jpg', 0, '2023-06-21 17:36:35');
INSERT INTO `data_info` VALUES (169, 34, '樱桃', '褐斑穿孔病', '樱桃褐斑穿孔病，主要危害叶片和新梢，发病症状叶表初生针头大小带紫色的斑点，后扩大为圆形褐色斑', '5-6月', '在温暖、多雨的条件樱桃褐斑穿孔病易发病。樱桃树树势弱、园内湿气大或夏季干旱也是诱发褐斑穿孔病的发生。褐斑穿孔病的病菌可以在落叶或枝梢病部越冬，在第二年借风、雨或气流传播。 主要是水肥管理不当或感染病源造成的。', '彻底清除樱桃园的病枝病叶，与修剪下来的病枝一起焚烧。在干旱或雨季时及时对樱桃园的浇水或排水，防止园内积水或湿气多等病害诱因。对樱桃树科学施肥，提高有机肥的施用比率，防止偏施氮肥。在樱桃发芽前，喷施一次4—5波美度石硫合剂。在6～8月病害高发期，每月喷1次等量式波尔多液(硫酸铜∶生石灰∶水=1∶1∶200)进行预防。喷施70%甲基硫菌灵可湿性粉剂800-1000倍液；50%多菌灵可湿性粉剂800-1000倍溶液；70%代森锰锌可湿性粉剂600-800倍液；3%中生霉素可湿性粉剂500-600倍；50%混合固硫悬浮剂500-600倍，每7-10天一次，共3-4次。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/7692e791-a03c-4e5d-a590-42410e91219f.jpg', 0, '2023-06-21 17:37:35');
INSERT INTO `data_info` VALUES (170, 34, '樱桃', '流胶病', '樱桃流胶病，是樱桃的一种综合性病害，发生极为普遍，发病原因复杂，很难彻底根治。', '5月~6月和8月~9月', '真菌、细菌危害，如褐斑病、干腐病、穿孔病等均能引起流胶。\n虫害蛀干造成的伤口诱发流胶，如红颈天牛、金缘吉丁虫、桑白介壳虫、金龟子等虫害。根部病害引起，如根癌病、腐烂病。机械损伤，过重修剪，剪锯口处理不合理，以及冻害、日灼等也能引起流胶。建园不合理。土壤黏重，通气、排水不良，园内积水，使树体产生生理障碍，也能引起流胶。', '加强栽培管理： 增施有机肥，避免偏施氮肥，培养健壮树势，提高树体抗逆性。土壤改良： 及时中耕松土，排水防涝，改善土壤通气状况。预防冻害： 避免花期和幼果期冻害。科学修剪： 避免过度修剪和过重伤锯口，减少枝条伤口。彻底清园： 秋末冬初彻底清除病叶,携带地面落叶,集中烧毁。药剂防治： 在病害高发期，可按50-100倍液稀释喷施主干和枝干，可得到理想效果。严重间隔7-10天再涂抹一次。涂抹的最适期为树液开始流动时，此时正是流胶的始发期，发生株数少流胶范围小，便于防治，减少树体养分消耗。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/37f1bc6d-26bf-4f03-9162-1252c301c6a3.jpg', 0, '2023-06-21 17:38:30');
INSERT INTO `data_info` VALUES (171, 34, '樱桃', '细菌穿孔病', '樱桃细菌穿孔病是樱桃树常见的疾病，发病叶片上出现半透明水渍状淡褐色小点', '3月下旬至4月上旬', '樱桃细菌穿孔病发病原因主要是排水不良的果园或多雨年份发生。樱桃细菌穿孔病危害叶片、果实和枝条。叶片感病后会产生褐色水渍状小点，逐渐扩大成圆形的病斑，最后形成穿孔。果实受害后，果皮上会产生水渍状褐色圆形小点，最后扩大为暗紫色的病斑，并形成穿孔、裂果。枝条感病后皮层会呈红褐色，逐渐干枯、开裂和脱落。在温暖、多雨或高温季节，该病易发生。如果樱桃园地势低洼、土质黏重、阴封光照、通风不畅处、花前或花期多雨等，会加剧樱桃细菌穿孔病的发生。', '彻底清园，发芽前喷施石硫合剂等。幼果期至采果后喷施农用链霉素、新植霉素、中生菌素等。果实套袋，避免果实直接接触外界环境，减少病菌侵染机会。加强果园管理，合理密植，注重通风透光，降低湿度，防止土壤过度潮湿。\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/cf9de397-4e2f-424b-bab3-c7189db09c08.jpg', 0, '2023-06-21 17:39:17');
INSERT INTO `data_info` VALUES (172, 11, '番茄', '晚疫病水霉菌', '番茄晚疫病水霉菌是引起番茄晚疫病的真菌，也称为番茄晚疫霉。该病害在全球范围内广泛存在，是影响番茄生产的重要病害之一。该病害主要通过叶片、茎、果实等部位的气孔和伤口侵入植株，引起植株组织中的水分流失和营养物质消耗，导致植株生长发育不良、凋萎死亡。', '春夏季节', '气候条件：该病害喜欢温暖潮湿的环境，并且适宜的温度为18-27℃，相对湿度为90%以上。在这种环境下，病原菌易于生长繁殖，并迅速传播。土壤条件：土壤湿度过大，土层深度较浅，通风性较差的地区更容易出现该病害。植株品种：不同品种的番茄具有不同的抗病能力。一些品种相对较为耐病，而另一些品种则容易受到病害侵袭。病原菌：番茄晚疫病的病原菌是一种真菌，可以通过空气、水滴、工具等多种途径传播和扩散。病原菌在植物体内繁殖，产生病斑和病菌孢子，进一步感染新的植物。', '种植抗病品种：选择抗病性强、适合当地生长条件的品种进行种植，能够有效防止病原菌的感染和传播。加强管理：在番茄栽培过程中，加强对土地、水源等环境的管理，合理施肥、灌溉等，保持适宜的生长条件，有利于提高番茄抵御病害的能力。定期清除病残体：采摘病部组织，及时清除残留物，减少病菌的生长环境，有助于阻止病害的继续传播。使用化学药剂：如有必要，可以使用合适的化学药剂进行防治，但要注意药剂使用的安全性和正确性，以避免对环境和人体造成不良影响。\n\n生物防治：可使用生物防治剂，如拮抗菌、磷酸溶菌酶等，以抑制病原菌的生长和繁殖。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/c8b3bc17-194e-41bf-a925-9667f0b14b65.jpg', 0, '2023-06-28 18:27:47');
INSERT INTO `data_info` VALUES (173, 11, '番茄', '叶斑真菌', '番茄叶斑真菌是一种引起番茄叶部病害的真菌，也被称为番茄黄化曲叶病菌。其科学名称为Septoria lycopersici Speg，属于担子菌门真菌纲的丝状菌。', '春季和秋季', '病原菌：病原真菌Septoria lycopersici Speg是引起番茄叶斑病的主要病原体。这种真菌可以通过种子传播、风、水等途径在田间传播，其孢子可以在番茄叶片上孵化并侵染感染。气候条件：气温较低、湿度较高是番茄叶斑真菌易于发生的典型气候条件。在这样的气候条件下，真菌繁殖迅速，感染叶片的机会也更多。此外，明显的温度变化和高温高湿的气候条件也有可能造成病害的爆发。土壤和植株管理：土壤缺乏养分、植株密度大、通风不良、土壤过于湿润都容易导致病害发生。此外，早期病斑未得到及时清除，也可能使真菌继续侵染植株，促进病害的传播。病害耐性：一些番茄品种因为缺乏抗病性或者是抵抗力不足，容易受到真菌感染，从而导致叶斑病害的发生。', '农业措施：选择抗病性较强的品种进行种植，定期清理病残体和采取轮作制度，增加植株间距以提高通风条件。此外，合理施肥、控制灌水量、适时修剪等管理措施也有助于减少病害的发生。药剂防治：如果出现大面积的病害，可以使用化学药剂进行防治。常用的防治药剂包括氧化乐果、三唑酮、百菌清等杀菌剂，需按照说明书严格使用，注意剂量和喷洒时间。生物防治：利用能够抑制真菌繁殖的微生物来进行防治，例如，利用放线菌、链霉素等微生物制剂进行喷洒，或者是通过混播含有抗病性菌株的有机肥料等方式来增加土壤微生物群落的多样性，从而减少真菌病害的发生。预防为主：在番茄种植期间加强监测，注意农作物健康成长，定期对植株进行检查，及时发现病害的早期症状，采取相应的措施避免病害扩散。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/534011ef-a797-477c-ad6f-3f4525f3f4a5.jpg', 0, '2023-06-28 18:28:30');
INSERT INTO `data_info` VALUES (174, 23, '白菜', '虫洞', '白菜虫洞是由蚜虫、食心虫等害虫危害引起的，虫口钻入植株组织后，破坏了细胞结构，导致植株幼嫩部分出现圆形或不规则形状的凹洞', '春季和秋季', '白菜虫洞的发生则是由蚜虫、食心虫等害虫钻入植株组织破坏细胞结构所导致，在夏季和秋季繁殖活跃，同时也可能会影响植物本身的免疫力，使其更易受到其他病害的侵袭。', '加强田间管理：保持田间清洁，及时清除田间残留物和杂草，保障作物健康生长。定期检查：定期检查白菜叶片是否有虫洞，一旦发现及时进行防治，以免虫害扩散。生物防治：可以使用一些生物制剂，如广谱杀虫菌、壮防丹等进行防治', 'https://etrees.oss-cn-shanghai.aliyuncs.com/29fa1d0c-cf27-4a7a-8b22-4a2ec04b5c92.jpg', 0, '2023-06-28 18:28:59');
INSERT INTO `data_info` VALUES (175, 11, '番茄', '卷曲病毒', '卷曲病毒主要感染茄科植物，如番茄、辣椒、茄子等作物，会导致叶片卷曲变形、植株生长迟缓、果实减产等问题，严重时可能导致植物死亡。', '夏秋季', '该病的发病原因主要是由白粉虱（Bemisia tabaci）传播的病毒引起。白粉虱作为TYLCV的主要传播媒介，在吸食感染了该病毒的植物汁液后，会将病毒带入其体内，然后再通过吸食未感染植物的汁液将病毒传播给宿主植物。', '选用抗TYLCV的品种是防治该病的重要措施之一，可通过培育高抗力品种来减少病原体在实际生产中的危害。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/6ca53ce3-0bb0-4fe6-b703-70548c0faa29.jpg', 0, '2023-06-28 18:29:29');
INSERT INTO `data_info` VALUES (176, 20, '玉米', '小叶斑病', '小叶斑病：又称玉米斑枯病，由真菌青枯链格孢属（Curvularia lunata）引起。症状主要表现为玉米叶片上出现黑色斑点，斑点大小一般在1-3毫米之间，病斑颜色较深，呈圆形、半圆形或不规则形，有时还可以在病斑边缘发现白色菌丝。感染严重的玉米植株叶片枯黄、甚至死亡，严重影响产量。\n', '夏季到秋季', '小叶斑病的发病原因：主要是由真菌青枯链格孢属感染引起的。该菌一般通过玉米种子等途径传播，当气温在25-35℃，空气湿度高（70%以上）时，病原体易于生长繁殖，从而引起病害的发生。', '选择抗病性强的品种：在种植玉米的时候要尽量选用抗病性好的品种，这样可以提高植株的抵抗力，降低患病的风险。加强田间管理：及时清理田间的玉米杂草、秸秆等残留物，减少病原体的藏匿和繁殖。避免玉米密植，保持适当的通风透气，避免长时间高湿度环境的形成。合理施肥：注意适量施肥，避免过度施肥或缺乏养分，维持良好的土壤环境，提高植株的抵抗力。使用化学药剂：可以使用有效的化学药剂进行防治，但必须按照标准施用，避免对环境带来负面影响。另外，为了防止病菌产生耐药性，应轮换使用不同类型的药剂。生物防治：可以用一些天然的生物制剂进行防治，如枯草芽孢杆菌、木霉菌等\n\n', 'https://etrees.oss-cn-shanghai.aliyuncs.com/f93ff796-01f0-474a-97b1-dcd2b34aada8.jpg', 0, '2023-06-28 18:30:02');
INSERT INTO `data_info` VALUES (178, 35, '石榴', '干腐病', '石榴干腐病是由石榴垫壳孢菌或葡萄座腔菌侵染所引起的、发生在石榴上的一种病害。该病主要危害果实，也侵染花蕾、花朵、果台、新梢。石榴干腐病是石榴的重要病害，在中国南方常见，采收期病果率10%左右，严重者达60%以上。贮藏期也可造成大量烂果。', '5月中旬到8月下旬', '病原菌：结合形态和分子生物学鉴定，将石榴果实干腐病病原菌鉴定为石榴垫壳孢菌，属半知菌类真菌；将石榴枝干干腐病病原菌鉴定为葡萄座腔菌，属子囊菌门真菌。由于人为的修剪、绑扎、刮皮等操作造成的伤口，为病菌的入侵提供了条件。栽培管理：管理不当，如干旱、水涝、负载过多、营养不良等都会为病菌的滋生提供条件。环境条件：如温度、湿度、光照等都会影响树体的生长状况，从而影响病菌的繁殖和传播。', '清除病原：在干旱年份或季节通过深翻改土、增施磷、钾肥来提高树体抗病能力。在萌芽前摘除树上干僵病果，剪除刮净病枝、皮，烧毁或深埋。病疤锯口用40%福美砷100倍液加0.5%渗透剂涂刷消毒。萌芽前全树喷3～5度石硫合剂，开花前后的发病盛期喷布50%退菌特或40%多菌灵800倍液。开花末期的6月中下旬，出现主干基部环状坏死现象，可利用根际萌蘖枝行桥接补救。从9月初起结合防虫，果面喷50%退菌特或40%多菌灵600～800倍液，或40%甲基托布津或40%代森锰锌800～1000倍液。加强栽培管理：秋季对石榴树进行施肥，每棵树施入土杂肥50公斤左右，并且配合一些复合肥，以促其生长。另外，还要对石榴树的树冠进行修剪，以控制树冠的大小，防止树冠过大而影响果实的生长。及时清洁果园：在石榴的果实成熟采摘之后，将果园中的杂草清除，并且及时将烂果、病虫果、残果清理干净，以减少果园中的病菌滋生。药剂防治：在石榴开花之前，使用50%多菌灵可湿性粉剂800倍液进行喷雾防治，以防止石榴干腐病的发生。在石榴坐果之后，使用45%代森铵水剂300倍液对石榴树进行喷雾防治，以保护果实。在干腐病发生严重的时候，可以使用甲基托布津可湿性粉剂800倍液进行喷雾防治。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/b964dee9-1c09-49c1-87a7-94d1f8fc4d31.jpg', 0, '2023-06-28 18:30:55');
INSERT INTO `data_info` VALUES (179, 35, '石榴', '桃小食心虫', '榴桃小食心虫，又名桃蛀果蛾，简称“桃小”，属鳞翅目，果蛀蛾科。', '7月上旬', '石榴桃小食心虫发病的原因主要是由于桃小食心虫的幼虫多由果实胴部或底部蛀入石榴果内，在果肉中纵横穿食危害，或直接蛀入果心，虫道弯曲，充满褐色虫粪，形成豆沙馅。幼虫老熟后多从果实胴部脱果，在果面上留下2~3毫米的脱果孔。被咬的脱果孔外常有新鲜虫粪，脱果孔的虫道无幼虫吐的丝。', '消灭越冬幼虫：在树干周围1米范围内冬翻晒茧或春翻地面，一般深翻5厘米左右，破坏越冬茧生存环境。在树干上绑草把，诱集幼虫和蛹，收集烧毁。药剂防治：田间调查，当卵果率达到1%至2%时，及时喷30%桃小灵乳油2000倍液或25%杀灭菊酯。在成虫发生期和幼虫孵化期，用2.5%功夫乳油2000倍或25%灭幼脲3号胶悬剂2000-3000倍液，或5%卡死克乳油1000倍液防治，都可获得较好的杀卵效果。人工摘除虫果：在桃小食心虫发生期内，发现虫果时要及时摘除，集中用药处理。在成虫产卵前给果实套袋，可阻止幼虫为害。\n果实套袋：对于优质品种或在人力较充足的条件下，可用废纸作成纸袋，在成虫产卵前套袋，果实成熟前7天去袋，可避免为害。\n树盘覆地膜：根据幼虫脱果后大部分潜伏于树冠下土中的特点，成虫羽化前，可在树冠下地面覆盖地膜，以阻止成虫羽化后飞出。\n药剂处理土壤：越冬幼虫出土期，可用50%地亚农；在山地果园，可用40%敌马粉直接在树冠下喷施，每亩5～8公斤。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/6c9ae84e-eab9-4e33-ae98-66bb4e6ed3e0.jpg', 0, '2023-06-28 18:32:20');
INSERT INTO `data_info` VALUES (180, 35, '石榴', '炭疽病', '石榴炭疽病是由半知菌类真菌侵染引起的，发生在石榴的一种病害。该病主要危害叶、枝和果实，叶片染病产生近圆形褐色病斑，枝条染病断续变褐，果实染病产生近圆形暗褐色病斑，有的果实边缘发红，无明显下陷现象，病斑下面果肉坏死，病部生有黑色小粒点，即病原菌的分生孢子盘。', '4-5月和7-8月', '病原菌：结合形态和分子生物学鉴定，将石榴果实干腐病病原菌鉴定为石榴垫壳孢菌，属半知菌类真菌；将石榴枝干干腐病病原菌鉴定为葡萄座腔菌，属子囊菌门真菌。树体伤口：由于人为的修剪、绑扎、刮皮等操作造成的伤口，为病菌的入侵提供了条件。\n栽培管理：管理不当，如干旱、水涝、负载过多、营养不良等都会为病菌的滋生提供条件。环境条件：如温度、湿度、光照等都会影响树体的生长状况，从而影响病菌的繁殖和传播。', '加强栽培管理：秋季对石榴树进行施肥，每棵树施入土杂肥50公斤左右，并且配合一些复合肥，以促其生长。另外，还要对石榴树的树冠进行修剪，以控制树冠的大小，防止树冠过大而影响果实的生长。及时清洁果园：在石榴的果实成熟采摘之后，将果园中的杂草清除，并且及时将烂果、病虫果、残果清理干净，以减少果园中的病菌滋生。药剂防治：在石榴开花之前，使用50%多菌灵可湿性粉剂800倍液进行喷雾防治，以防止石榴炭疽病的发生。在石榴坐果之后，使用45%代森铵水剂300倍液对石榴树进行喷雾防治，以保护果实。在炭疽病发生严重的时候，可以使用甲基托布津可湿性粉剂800倍液进行喷雾防治。', 'https://etrees.oss-cn-shanghai.aliyuncs.com/02aa506d-e297-4d9f-8845-0fac27e86a0f.jpg', 0, '2023-06-28 18:33:05');
INSERT INTO `data_tips` VALUES (43, '使用生物防治方法，如昆虫寄生虫或细菌，替代化学农药。');
INSERT INTO `data_tips` VALUES (44, '使用有机农药和杀虫剂时，遵循正确的使用方法和剂量');
INSERT INTO `data_tips` VALUES (45, '定期清洁花盆和种植容器，消毒并更换土壤，防止土壤传播病虫害。');
INSERT INTO `data_tips` VALUES (46, '注意植物的适宜生长温度和湿度范围，提供合适的环境条件。');
INSERT INTO `data_tips` VALUES (47, '防止野生动物进入种植区域，避免它们破坏植物或传播病菌。');
INSERT INTO `data_tips` VALUES (48, '隔离新购买的植物一段时间，观察是否有潜在的病虫害问题。');
INSERT INTO `data_tips` VALUES (49, '定期修剪植物，保持良好的通风和空气流动，减少病虫害风险。');
INSERT INTO `data_tips` VALUES (50, '合理管理土壤营养，确保植物充分吸收所需营养，提高抵抗力。');
INSERT INTO `data_tips` VALUES (51, '不随意引入外来物种，以免破坏生态平衡和引发新的病虫害问题。');
INSERT INTO `data_tips` VALUES (52, '确保植物获得足够的阳光，增强其光合作用和免疫系统。');
INSERT INTO `data_tips` VALUES (53, '注意植物的生长状态和外观异常，及时发现问题并采取措施。');
INSERT INTO `data_tips` VALUES (54, '种植植物之间保持适当的距离，以避免病菌传播与竞争。');
INSERT INTO `data_tips` VALUES (55, '整理园区周围的杂草和废弃物，减少病虫害的栖息地。');
INSERT INTO `data_tips` VALUES (56, '使用物理防治方法，如捕虫纸、黏虫板或陷阱，吸引并捕捉害虫。');
INSERT INTO `data_tips` VALUES (57, '定期修剪和整理植物，以提高空气流通和减少病虫害的藏身之处。');
INSERT INTO `data_tips` VALUES (58, '防止不明来源的植物材料进入种植区域，以避免引入新的病虫害。');
INSERT INTO `data_tips` VALUES (59, '在疫病高发季节或环境条件下增加监测频率，以便及早发现病害。');
INSERT INTO `data_tips` VALUES (60, '增加土壤健康，使用有机材料覆盖土壤以增强其保水');
INSERT INTO `data_tips` VALUES (61, '使用农业生态工程技术，如湿地建设或人工鱼塘，促进生态平衡。');
INSERT INTO `data_tips` VALUES (62, '注意植物的生长环境温度和湿度，避免过高或过低的极端条件。');
