INSERT INTO `shop_product` VALUES (10000017, 110, '化肥', '氮肥', '氮肥是一种用于植物生长的肥料，其主要成分是氮元素化合物。氮肥的作用是在土壤中提供足够的氮元素，帮助植物生长和发育，增加产量和提高品质', 15.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4de77b89-3e6e-4288-b108-bb8de1cb6464.jpg', '2023-06-01 09:59:06', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000018, 117, '病害治愈', '多菌灵', '多菌灵是一种杀菌剂，主要成分为甲基硫菌灵，可用于防治多种作物病害，包括叶斑病、锈病、褐斑病等。', 9.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b7a185b9-b3a0-4a31-90fc-a56f5cd41a18.png', '2023-06-01 09:59:06', '番茄叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000019, 117, '病害治愈', '腐霉灵', '腐霉灵是一种杀菌剂，主要成分为苯醚甲环唑，可用于防治作物的真菌和霉菌等病害', 8.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/12efd698-7f08-4239-b1fe-7660682a9a36.jpg', '2023-06-01 09:59:06', '番茄叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000020, 117, '病害治愈', '枯草芽孢杆菌', '枯草芽孢杆菌可以分解有机物质，促进土壤微生物群落的平衡，并且具有调节植物生长、抑制植物病原菌等多种生物学特性。', 18.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d1cb66fc-0a44-4918-845b-8f90f28f661e.jpg', '2023-06-01 09:59:06', '番茄叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000021, 117, '病害治愈', '氧化锌', '氧化锌（ZnO）是一种无机化合物，具有白色粉末状或颗粒状的外观', 14.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/cc8e0b58-1d8b-42b8-b556-609ba7b81ceb.png', '2023-06-01 09:59:06', '番茄叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000022, 117, '病害治愈', '硫酸铜', '硫酸铜是一种无机化合物，化学式为CuSO4。它是一种蓝色晶体，可溶于水，具有广泛的应用。', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8e83ff24-88e9-47e1-9ffd-7625f817d9ce.jpg', '2023-06-01 09:59:06', '葡萄黑腐病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000023, 117, '病害治愈', '苯醚甲环唑', '苯醚甲环唑是一种杀菌剂，化学名称为1-（4-氯苯基）-2-（2-甲氧基苯氧基）乙烷-1,2-二酮。它是白色晶体，可以稳定地存放在常温下，并且可以溶于水和有机溶剂。', 9.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/9da77b12-802e-4a42-b1a5-29371f0a8374.png', '2023-06-01 09:59:06', '葡萄黑腐病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000024, 117, '病害治愈', '强力霉素', '强力霉素是一种广谱抗生素，属于大环内酯类抗生素。它的分子式为C41H72N2O12，是一种白色至淡黄色晶体，可以溶于水和乙醇。', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4f692207-1861-448a-adba-223c4a92d490.jpg', '2023-06-01 09:59:06', '葡萄黑腐病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000025, 117, '病害治愈', '液体硫', '液体硫是一种无色或淡黄色的粘稠液体，在常温下很少见到。液体硫可以通过加热固态硫进行制备，其熔点为115.21摄氏度。', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/484cf53a-2764-49f3-a23c-dc74b9f976cf.png', '2023-06-01 09:59:06', '葡萄黑腐病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000026, 117, '病害治愈', '黑三嗪', '黑三嗪是一种广谱杀菌剂，主要用于防治作物病害', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/09e1e936-6697-49aa-b1a6-958a9a7ecd9e.jpg', '2023-06-01 09:59:06', '苹果黑星病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000027, 117, '病害治愈', '三唑酮', '三唑酮是一种新型广谱杀菌剂，可有效防治植物真菌性病害', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8d55fecc-db93-4b47-86c1-af957bfceef8.jpg', '2023-06-01 09:59:06', '苹果黑星病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000028, 117, '病害治愈', '草铵膦', '草铵膦一种广谱杀草剂，它能够有效地控制多种草本植物和某些灌木。其主要成分为草甘膦和氨基甲酸。', 15.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/9cc594f2-8fdf-4913-9fb6-ba60bd290b20.png', '2023-06-01 09:59:06', '苹果黑星病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000029, 117, '病害治愈', '地乐酚锰锌', '地乐酚锰锌是一种广谱性杀菌剂，主要成分为地乐酚、锰和锌', 14.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/5857fee0-f9e7-4c16-a8d9-b48a6690c282.jpg', '2023-06-01 09:59:06', '苹果黑星病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000033, 117, '病害治愈', '滴滴涕', '滴滴涕是一种广谱杀菌剂，可以防治玉米、小麦等多种农作物的真菌病害', 50.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/fb9412ad-6a6f-4f0c-a24d-8c44d926d96b.jpg', '2023-06-01 22:32:54', '玉米大叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000034, 117, '病害治愈', '滴滴涕', '这是一种广谱杀菌剂，可以防治玉米、小麦等多种农作物的真菌病害', 50.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/11d1011d-ccc6-483b-a44e-9802266bdfa3.jpg', '2023-06-01 22:33:34', '玉米小叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000035, 117, '病害治愈', '氧化乐果', '氧化乐果是一种广谱杀虫剂和杀线虫剂，属于甲基碳酰胺类农药。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b24eb5ec-360d-47ef-9833-39f22955fe72.jpg', '2023-06-01 22:34:36', '玉米大叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000036, 117, '病害治愈', '氧化乐果', '氧化乐果是一种广谱杀虫剂和杀线虫剂，属于甲基碳酰胺类农药。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/96e31a41-2dff-4745-a27b-6b6d360368e3.jpg', '2023-06-01 22:35:24', '玉米小叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000037, 117, '病害治愈', '托布津', '托布津是一种广谱杀菌剂，属于三唑类杀菌剂。', 14.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8ef190d4-8fe5-435f-b6c9-a293a90207b6.jpg', '2023-06-01 22:36:12', '玉米大叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000038, 117, '病害治愈', '托布津', '托布津是一种广谱杀菌剂，属于三唑类杀菌剂。', 14.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/0707f805-e28e-4388-ba54-af960a1b0781.jpg', '2023-06-01 22:36:46', '玉米小叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000039, 117, '病害治愈', '咪鲜胺', '咪鲜胺是一种内吸性广谱杀菌剂，对多种植物真菌病害都有较好的防治效果', 6.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/3f516872-cc09-4957-a098-a9c39223a03d.jpg', '2023-06-01 22:37:39', '玉米大叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000040, 117, '病害治愈', '咪鲜胺', '咪鲜胺是一种内吸性广谱杀菌剂，对多种植物真菌病害都有较好的防治效果', 6.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/852171d6-999f-4493-b5b8-dce61d0b6776.jpg', '2023-06-01 22:38:12', '玉米小叶斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000041, 117, '病害治愈', '甲基阿维菌素', '甲基阿维菌素是一种杀虫剂，是氨基磺酸酯类农药，它的作用机制是通过干扰昆虫神经系统，抑制其肌肉活动和食欲，最终导致虫体死亡。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/567798dd-049f-4c2d-9dd8-77e8e68a09d8.jpg', '2023-06-01 22:43:03', '番茄黄叶病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000042, 117, '病害治愈', '甲基阿维菌素', '甲基阿维菌素是一种杀虫剂，是氨基磺酸酯类农药，它的作用机制是通过干扰昆虫神经系统，抑制其肌肉活动和食欲，最终导致虫体死亡。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/252052af-6ef7-433d-aa2d-bbc9a08cb3fd.jpg', '2023-06-01 22:43:29', '番茄卷曲病毒', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000043, 117, '病害治愈', '乙酰甲胺', '乙酰甲胺是一种杀虫剂，属于氨基甲酸酯类农药。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/88f189e4-5a0b-4236-a167-df6e1b0195dd.jpg', '2023-06-01 22:45:33', '番茄黄叶病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000044, 117, '病害治愈', '吡虫啉', '吡虫啉是一种新型高效的杀虫剂，属于氯氰菊酯类农药。', 4.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/42c3ef69-fbd9-462c-b204-e08aaec0b5b8.jpg', '2023-06-01 22:46:44', '番茄黄叶病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000045, 117, '病害治愈', '吡虫啉', '吡虫啉是一种新型高效的杀虫剂，属于氯氰菊酯类农药。', 4.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/73a14196-f18d-447a-82c0-c6710f3318c0.jpg', '2023-06-01 22:47:00', '番茄卷曲病毒', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000046, 117, '病害治愈', '硅酸二铝', '硅酸二铝，是一种天然的矿物质', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/77b98d7b-58ca-4f70-bcbf-7314e2c3a80f.jpg', '2023-06-01 22:47:57', '番茄黄叶病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000047, 117, '病害治愈', '硅酸二铝', '硅酸二铝，是一种天然的矿物质', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/92b733c8-9249-4311-bd47-9b817ca434b8.jpg', '2023-06-01 22:48:09', '番茄卷曲病毒', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000048, 117, '病害治愈', '甲基硫菌灵', '甲基硫菌灵是一种广谱性杀菌剂，对霉斑病有治疗效果', 7.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/0570ccde-d6a7-4e6e-a6f7-c53b8d20b368.jpg', '2023-06-01 22:49:30', '白菜霉斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000049, 117, '病害治愈', '甲基硫菌灵', '甲基硫菌灵是一种广谱性杀菌剂，对霉斑病有治疗效果', 7.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/568518d5-658f-4208-b4b9-e0a03e130a33.jpg', '2023-06-01 22:49:38', '白菜虫洞', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000050, 117, '病害治愈', '噻菌灵', '噻菌灵是一种广谱性杀菌剂，可用于防治霉斑病和其他病害', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/77523e36-0cbe-4f3e-afce-6b49feac4f23.jpg', '2023-06-01 22:50:27', '白菜霉斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000051, 117, '病害治愈', '噻菌灵', '噻菌灵是一种广谱性杀菌剂，可用于防治霉斑病和其他病害', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d560bae6-11ce-4d7f-89c9-a3d665e54c15.jpg', '2023-06-01 22:50:45', '白菜虫洞', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000052, 117, '病害治愈', '菌膜唑', '菌膜唑是一种新型杀菌剂，具有广谱性、强效性和长效性等优点，可用于防治霉菌和真菌等病害。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4097213e-e253-4a3e-9297-6b372f7244be.jpg', '2023-06-01 22:51:55', '白菜霉斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000053, 117, '病害治愈', '菌膜唑', '菌膜唑是一种新型杀菌剂，具有广谱性、强效性和长效性等优点，可用于防治霉菌和真菌等病害。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b9511087-9ced-42f4-8a80-59e7af5944ed.jpg', '2023-06-01 22:52:09', '白菜虫洞', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000054, 117, '病害治愈', '氧氟沙星', '氧氟沙星是一种新型杀菌剂，对霉斑病和许多其他植物病害均有良好的治疗效果。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/3a8fc258-a04d-4e18-a345-4288cc71f728.png', '2023-06-01 22:52:43', '白菜霉斑病', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000055, 117, '病害治愈', '氧氟沙星', '氧氟沙星是一种新型杀菌剂，对霉斑病和许多其他植物病害均有良好的治疗效果。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/21aed4bb-0bb3-4574-b01d-051a9e4296da.png', '2023-06-01 22:52:57', '白菜虫洞', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000056, 110, '化肥', '中量元素化肥', '中量元素化肥是指在植物生长过程中所需要的中量元素制成的化学肥料。中量元素一般包括镁、硫、钙、钾等元素，这些元素对于植物的生长、营养和抗病能力都起到了至关重要的作用', 21.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/f57b8b8d-10e7-4bb3-bb83-b99727d3c4b9.jpg', '2023-06-01 22:55:01', '', '2023-06-21 20:05:11');
INSERT INTO `shop_product` VALUES (10000057, 110, '化肥', '生物肥料', '生物化肥是指利用微生物或生物有机质等天然物质制成的一种肥料。与传统的化学肥料相比，生物化肥具有更好的环保性和可持续性，并且对土壤、作物的抗逆性和品质提升也更加显著。', 6.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/5a3d204f-a0ef-40f9-b8cd-40ce718b3f84.jpg', '2023-06-01 22:55:38', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000058, 110, '化肥', '多维场能浓缩有机肥', '多维场能浓缩有机肥是一种利用现代科技手段精制而成的有机肥料。它是由多种天然有机物质经过高温高压、微生物处理和分离等复杂工艺加工而成的，具有碳氮比适宜、营养全面、含盐量低、无毒无害等特点。', 8.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/78a0b42b-059b-4573-b9b1-c7deadc86623.jpg', '2023-06-01 22:56:38', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000059, 110, '化肥', '磷肥', '磷肥是一种含有磷元素的化学肥料，它是指能提供植物生长所需磷元素的肥料。在植物生长过程中，磷肥可以促进植物根系的发育和吸收能力的提高，从而增强植物的抗寒、抗旱、抗病能力，提高产量和改善品质。', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/cd14693a-9f53-4829-8c3c-97631ff5b915.jpg', '2023-06-01 22:57:14', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000060, 110, '化肥', '速效肥料', '速效肥料是指向植物提供的养分能够快速被吸收利用，同时在短时间内可以产生显著的促进植物生长的效果。与缓释肥料相对应，速效肥料的养分释放速度较快，一般在施用后数天至数周内即可被植物吸收利用。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/5068f06c-cd15-4d93-aeff-5b236445cad4.jpg', '2023-06-01 22:57:56', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000061, 110, '化肥', '缓效肥料', '缓效肥料是指能够在较长时间内持续为植物提供养分，而且养分释放速度相对较慢的肥料。与速效肥料不同，缓效肥料能够满足植物长期生长发育需要，且不容易引起肥料过剩和土壤污染等问题。', 9.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8cd73d3e-17a8-4ccd-8e3b-63211ce24719.jpg', '2023-06-01 22:58:24', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000062, 110, '化肥', '控释肥料', '控释肥料是一种新型的肥料，它能够控制肥料中养分的释放速度和时机，从而达到延长肥效、减少浪费、提高利用率等效果。控释肥料是在原有肥料上加工而成，控制释放养分的方式包括化学反应、物理控制和生物降解等方法。', 4.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d1df6b7a-6c3b-4e12-83ec-279485b2d8fe.jpg', '2023-06-01 22:58:50', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000063, 110, '化肥', '中性化学肥料', '中性化学肥料，又称平衡肥料，是指氮、磷、钾三大元素在肥料中的含量相对平衡，不偏向任何一种元素过多，达到较为均衡的状态。这种肥料能够提供作物生长所需的三大主要养分，并能够促进作物整体生长发育。。', 6.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/14247126-bcbc-4aca-8db1-47e5920b69ea.jpg', '2023-06-01 22:59:23', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000064, 111, '助农工具', '爬山虎运输车', '爬山虎运输车，是一种专门用于越野运输和登山行驶的车辆。它可以在复杂的路况下保证良好的行驶性能和通过性能，因此通常被用于不便其他车辆通过的高山、峡谷、林区等地区进行采集、救援、探险等活动。', 28500.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/934c946b-14f4-4892-a349-04989a0115af.jpg', '2023-06-01 23:00:07', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000065, 111, '助农工具', '锰钢三角锄', '锰钢三角锄是一种专门用于园艺、农业、林业等行业的常见手工工具，其主要功能是用于挖掘、翻土、松土、除草等作业。它由锰钢制成，具有锋利耐用、强度高等特点，使得其在野外作业中表现出色，使用寿命长。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/198c46e7-5c40-4bd6-a82d-4271ef5ad362.jpg', '2023-06-01 23:00:46', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000066, 111, '助农工具', '搂草耙子', '搂草耙子，又称为草膜、扫把等，是一种用于农业、园林、家庭等场所的工具。它主要用于清理草坪、秸秆等杂物，将其集中起来，方便后续处理。', 9.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/566fe905-3dce-46ee-938e-d699b6885664.jpg', '2023-06-01 23:01:21', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000067, 111, '助农工具', '手摇玉米脱粒机', '手摇玉米脱粒机是一种用于将玉米籽粒从玉米的芯部分离析出来的机器，它主要由支架、传动装置和振动筛等部分组成。', 70.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/92501727-096e-4e7c-9804-66018bfe5e48.png', '2023-06-01 23:01:51', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000068, 111, '助农工具', '铺地膜神器', '铺地膜神器是一种农业机械，主要用于在地面上铺设防渗、保温、抑草等用途的塑料薄膜，以保证作物生长的质量和产量。', 32.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/f788154f-0d55-4e5a-925c-d845c21927b7.jpg', '2023-06-01 23:02:32', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000069, 111, '助农工具', '移苗器', '移苗器是一种农业机械，主要用于在育苗盘或育苗箱中移栽幼苗，以提高作物生产效率和减轻劳动强度。', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/6d9b87b6-9db9-4a4a-a605-213d4b817ddb.jpg', '2023-06-01 23:03:12', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000070, 112, '耕作工具', '犁头', '犁头是一种农业机械配件，主要用于拖拉机、手扶拖拉机等农机上，用来深松耕作、翻斗耕作、开沟、埋肥等作物管理活动中，将土壤翻转和深度处理的工具。', 18.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/646dcdd2-f5e7-4845-a2b8-809a9799dc8d.png', '2023-06-01 23:03:44', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000071, 112, '耕作工具', '锄头', '锄头是一种常见的农具，用于在农田中进行松土、除草、深耕等工作，可以分为直柄锄和把手锄两种类型', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b7b1551c-0536-45d9-bce1-c8e165f77949.png', '2023-06-01 23:04:17', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000072, 112, '耕作工具', '锄子', '锄子是一种常见的农具，也可用于花园、草坪等地的耕作和清理工作。锄子主要由锄头、柄杆和把手组成，其工作原理是通过锄头切割和松土，帮助植物更好地吸收养分、释放根系和根茎，同时可以除去作物间的杂草和草根。', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/6d2e886d-0b2d-4752-9c6d-aab6cf5db90a.jpg', '2023-06-01 23:04:50', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000073, 112, '耕作工具', '种植机', '种植机是一种用于大规模农业生产的机器，用于在田地里快速、高效、准确地完成作物的种植。其工作原理是通过机械化的方式将种子按照一定的间距和深度直接埋在土壤中，从而达到节约时间、劳动力，提高生产效率的目的。', 2000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b61ba45c-ecac-44e9-8e90-7625a05823d5.jpg', '2023-06-01 23:05:26', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000074, 112, '耕作工具', '喷雾器', '喷雾器是一种应用广泛的农业机械设备，主要用于农田、果园、草坪等地方的植物防治、施肥、灌溉等作业。它的工作原理是通过压缩空气或电动马达带动液体进入喷嘴，将药液、肥料或水以微小颗粒的形式均匀地喷洒在被处理的植物表面或周围环境中。。', 78.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/a236e28b-e72b-43a6-9c00-6b3e7e0850d7.jpg', '2023-06-01 23:05:52', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000075, 112, '耕作工具', '草帘', '草帘是一种传统的农业生产技术，也是一种环保、节能、可持续发展的生态农业技术。它主要是利用树枝、草木、竹子等天然植物材料编织而成的遮荫棚，用于农田的保温、防风、保墒、保湿等工作。。', 4.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/64193f88-1ddb-458a-8f3c-bcc111b5ef9d.jpg', '2023-06-01 23:06:49', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000076, 112, '耕作工具', '圆盘切割机', '圆盘切割机，又称为草地切割机或草皮机，是一种常用的农业机械设备，主要用于割草、修剪和收割草地、牧草地、花园等地方的草坪', 150.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/dd826170-955d-493c-873e-28ffbe05f1ed.jpg', '2023-06-01 23:07:14', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000077, 112, '耕作工具', '手推式播种机', '手推式播种机是一种农业机械设备，主要用于种植作物和农业生产中的精细化操作', 230.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/bd16108b-23d5-4c69-ac6f-d755a834d09d.jpg', '2023-06-01 23:07:39', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000078, 112, '耕作工具', 'PH测试仪', 'PH测试仪是一种广泛应用于实验室、水质检测、农业、环保等领域的仪器设备，主要用于测试液体或溶液中的pH值。', 98.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b6d0a245-d31b-4b01-a664-3925c2866c1f.jpg', '2023-06-01 23:08:15', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000079, 112, '耕作工具', '大气温度机', '大气温度机，也叫做气象观测站，是一种用于测量和记录气象环境参数的设备，主要包括气温、风速、风向、湿度、气压、降水等各项气象参数。', 124.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b3daf5de-cc8c-4e28-a665-ee95f98cf5ad.jpg', '2023-06-01 23:08:42', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000080, 113, '大型器械', '联合耕作机', '联合耕作机，也叫旋耕机，是一种农业机械设备，用于耕田、作物翻耕、松土和覆盖秸秆等工作。', 75000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/6aa2ea51-a016-4376-b745-eda828b16a57.jpg', '2023-06-01 23:09:35', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000081, 113, '大型器械', '土壤耕作机', '土壤耕作机采用发动机或动力输出装置驱动，通过旋转刀盘将土壤拨起、翻转和松散，以便肥料和水分更加容易渗透到土壤深层', 68000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d6e44a29-9540-47ed-969b-77bdadc7912c.jpg', '2023-06-01 23:10:04', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000082, 113, '大型器械', '链轨式微耕机', '链轨式微耕机，是一种小型、便携式的农业用具，主要用于田间微型作业、施肥和除草等操作。它采用齿轮传动或链条传动技术，将发动机的动力直接传送到刀盘上，通过高速旋转的方式将土壤翻动，达到耕作的效果。', 2050.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/75d05fe3-ab7c-43e1-93da-cdb0d1a2ac16.jpg', '2023-06-01 23:10:44', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000083, 113, '大型器械', '农用挂车', '农用挂车，是一种专门为农业生产设计的交通工具。它主要由挂车底盘、车厢和支撑系统等部分构成。', 57000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/355717bb-9146-42a6-85a0-9276b3958bcf.jpg', '2023-06-01 23:11:30', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000084, 113, '大型器械', '牵引式农业机械', '牵引式农业机械是指那些依靠其他动力源对其进行运动的农业机械，例如拖拉机、履带车等。', 300000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4cb06118-49e5-4606-940c-381508074bb0.jpg', '2023-06-01 23:12:05', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000085, 113, '大型器械', '独轮微耕机', '独轮微耕机是一种小型、轻巧的微耕机，它通常由一个独立的轮子和一个耕作部件组成。', 3000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/f5f19a9a-a8fc-41c1-b3d2-0b4b641ebf0d.jpg', '2023-06-01 23:12:35', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000086, 113, '大型器械', '施肥机', '施肥机是一种广泛应用于农业、园林、草坪管理等领域的机器，它主要是用来完成对植物施肥的作业。', 10000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8ffcf5cb-35de-4be4-a553-2253df36dd7d.jpg', '2023-06-01 23:13:17', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000087, 114, '农业药品', '杀虫剂', '杀虫剂是一类用于杀灭或控制害虫的化学物质，他们在农业、林业、园艺以及家庭家具等领域发挥了重要的作用。', 50.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/50ac5e27-75be-4f4f-8413-bc23d5a9b8c5.jpg', '2023-06-01 23:13:50', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000088, 114, '农业药品', '杀菌剂', '杀菌剂是用于杀死或控制细菌、真菌、病毒等微生物的一类化学物质。', 70.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/bfb8f3df-96d7-4484-8f34-75a128d17ace.jpg', '2023-06-01 23:14:24', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000089, 114, '农业药品', '除草剂', '除草剂是一类用于控制或消灭杂草的化学药品。', 60.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/2785540b-7acc-4f29-bcfc-cd9d36ba5aa7.jpg', '2023-06-01 23:15:02', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000090, 114, '农业药品', '杀螨剂', '杀螨剂是一类专门用于控制、灭杀螨虫的化学物质。', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/29e8ff45-bd44-4494-8e59-8c737665c607.jpg', '2023-06-01 23:15:33', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000091, 114, '农业药品', '杀鼠剂', '杀鼠剂是专门用于控制、灭杀啮齿动物（如老鼠、田鼠、家鼠等）的化学药剂。', 30.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d861fd60-2609-4888-aea8-a49674f226b5.jpg', '2023-06-01 23:15:55', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000092, 114, '农业药品', '植物生长调节剂', '植物生长调节剂是一类用于控制植物生长和发育的化学物质，它们通过调控植物内部激素的合成、转运和代谢等途径，来促进或抑制植物的生长和发育过程。', 50.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b5912557-57d9-4674-8cea-be42a3129b70.jpg', '2023-06-01 23:16:35', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000093, 115, '病害防止', 'ZD-GSA1型农作物病虫害防治设备', 'ZD-GSA1型农作物病虫害防治设备是一种集智能控制与光学检测于一体的设备，主要用于农作物的病虫害防治。', 10000.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/050a4273-abc1-4565-a2e8-4ef7863a667f.jpg', '2023-06-01 23:17:03', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000094, 115, '病害防止', '地埋式诱捕器', '地埋式诱捕器主要由一个圆筒形容器、塑料盖、粘胶垫、药剂等组成，可以在地面以下安装，使害虫陷入粘胶垫中并被诱杀。', 80.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/fd35cdbc-191c-4c4c-9514-ffa8f38a2c8d.jpg', '2023-06-01 23:17:26', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000095, 115, '病害防止', '便携臭氧杀菌剂', '臭氧杀菌剂通过高压放电技术将空气中的氧气转化为臭氧，臭氧具有强氧化性和高效杀菌能力。', 700.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8279ef78-2329-4791-af21-4ed095a46b5e.jpg', '2023-06-01 23:18:09', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000096, 116, '农业书籍', '《农作物害虫光源诱空技术》', '《农作物害虫光源诱空技术》是一种以人工制造的高亮度光源来吸引和诱捕农作物中的害虫，从而达到防治害虫的目的。', 13.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/224b3738-ff0c-4fe4-bfb5-8557b532fdbb.jpg', '2023-06-01 23:18:41', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000097, 116, '农业书籍', '《农作物种植与科学养殖》', '《农作物种植与科学养殖》是一本介绍现代化农业生产技术的专业书籍。这本书涵盖了从农作物的选育、栽培管理到畜禽的饲养、疾病防治等方面内容', 9.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4bc0e5d2-d1c3-43d9-bb7a-620deb5ed297.jpg', '2023-06-01 23:19:04', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000098, 116, '农业书籍', '《农作物测土配方施肥技术》', '《农作物测土配方施肥技术》是一本针对现代农业生产技术的专业书籍，主要介绍了农作物的营养需求、土壤肥力、施肥方法和策略等。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b912fec9-0ec9-4dbb-afcd-43b090d929eb.jpg', '2023-06-01 23:19:43', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000099, 116, '农业书籍', '《中国农民手册》', '《中国农民手册》是由毛泽东领导的中国共产党中央革命根据地工作委员会编写的一本农村生产自救手册', 18.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/d57dd09d-8d8f-438d-bf92-df6a35037a4a.png', '2023-06-01 23:20:14', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000100, 116, '农业书籍', '《农作物病虫害防治技术研究》', '《农作物病虫害防治技术研究》是一本专门讨论农作物病虫害防治技术的著作', 19.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4865517a-44bd-48ce-8dd9-fda605d963b0.jpg', '2023-06-01 23:21:01', '', '2023-06-18 14:35:23');
INSERT INTO `shop_product` VALUES (10000101, 117, '病害治愈', '乙酰甲胺', '乙酰甲胺是一种杀虫剂，属于氨基甲酸酯类农药。', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/c316492e-0e5c-46db-9591-e335b86cefd1.jpg', '2023-06-21 20:37:26', '番茄卷曲病毒', '2023-06-21 20:37:26');
INSERT INTO `shop_product` VALUES (10000102, 117, '病害治愈', '醚菌酯', '醚菌酯是一种高效、广谱、新型杀菌剂。', 500.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/5d862289-c1d9-4bb2-bce1-4bcc414f9672.jpg', '2023-06-21 20:39:32', '草莓白粉病', '2023-06-21 20:39:32');
INSERT INTO `shop_product` VALUES (10000103, 117, '病害治愈', '乙嘧酚', '乙嘧酚是一种有机化合物为，淡黄色或浅棕色蜡状固体。。', 5.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/9c984d4d-69c7-4b85-a2a2-8fd9ccbd4e7b.jpg', '2023-06-21 20:40:00', '草莓白粉病', '2023-06-21 20:40:00');
INSERT INTO `shop_product` VALUES (10000104, 117, '病害治愈', '肟菌酯', '肟菌酯是一种含氟杀菌剂，具有高效、广谱、保护、治疗、铲除、渗透、内吸活性等特性', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/56154781-0c03-446d-8082-85e785242ed8.jpg', '2023-06-21 20:40:29', '草莓白粉病', '2023-06-21 20:40:29');
INSERT INTO `shop_product` VALUES (10000105, 117, '病害治愈', '四氟醚唑', '醚菌酯是一种高效、广谱、新型杀菌剂', 500.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/820f0923-8fcb-4538-8a1a-daea3ecd9594.jpg', '2023-06-21 20:41:04', '草莓白粉病', '2023-06-21 20:41:04');
INSERT INTO `shop_product` VALUES (10000106, 117, '病害治愈', '腈菌唑', '腈菌唑是一种农药杀菌剂，属于留醇合成抑制剂类，具有广谱和突出的离体杀菌活性，对真菌病害有很好的防治效果。', 480.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/0ccfc1b7-bd3d-4354-ab0a-02967e6cae0e.jpg', '2023-06-21 20:47:35', '番茄粉末状霉菌', '2023-06-21 20:47:35');
INSERT INTO `shop_product` VALUES (10000107, 117, '病害治愈', '氟硅唑', '氟硅唑，杀菌谱广，能治疗多种作物上的多种真菌性病害', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/b1a66a57-b703-4984-b7ae-875ab48cf8dc.jpg', '2023-06-21 20:48:11', '番茄粉末状霉菌', '2023-06-21 20:48:11');
INSERT INTO `shop_product` VALUES (10000108, 117, '病害治愈', '咯菌腈', '咯菌腈是一种化学物质,纯品为淡黄色粉末', 1400.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/1260b32e-9fb0-43bb-b3db-16b89abf7a18.jpg', '2023-06-21 20:49:01', '番茄粉末状霉菌', '2023-06-21 20:49:01');
INSERT INTO `shop_product` VALUES (10000109, 117, '病害治愈', '异菌脲', '异菌脲是一种有机物，白色结晶。', 200.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/0b6de60a-f506-4756-8877-34f59cc4c8ce.jpg', '2023-06-21 20:51:00', '番茄粉末状霉菌', '2023-06-21 20:51:00');
INSERT INTO `shop_product` VALUES (10000110, 117, '病害治愈', '霜脲·锰锌', '霜脲·锰锌是一种保护性杀菌剂，可用于防治低等真菌病害', 400.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/094ebb10-9a4f-459e-b203-9a6e14052e1f.jpg', '2023-06-21 20:55:00', '番茄晚疫病水霉菌', '2023-06-21 20:55:00');
INSERT INTO `shop_product` VALUES (10000111, 117, '病害治愈', '属霜霉威', '霜霉威是一种具有局部内吸作用的低毒杀菌剂，属氨基甲酸酯类。', 50.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/ec7cda58-ce76-4fdc-a3eb-b0858c98421d.jpg', '2023-06-21 20:55:40', '番茄晚疫病水霉菌', '2023-06-21 20:55:40');
INSERT INTO `shop_product` VALUES (10000112, 117, '病害治愈', '乙磷铝·锰锌', '乙磷铝·锰锌是一种有机化合物，由乙磷铝和代森锰锌混合而成。\n', 70.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/bc125eb4-d0b0-444c-90e1-206d871f8a3a.jpg', '2023-06-21 20:56:05', '番茄晚疫病水霉菌', '2023-06-21 23:29:21');
INSERT INTO `shop_product` VALUES (10000113, 117, '病害治愈', '烯酰吗啉', '烯酰吗啉是一种杀菌剂，属于吗啉类\n化合物，由乙磷铝和代森锰锌混合而成。\n', 500.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/ded1b7e5-c8b7-44c1-a5ed-8601f06d0f5d.png', '2023-06-21 20:56:42', '番茄晚疫病水霉菌', '2023-06-21 20:56:42');
INSERT INTO `shop_product` VALUES (10000114, 117, '病害治愈', '戊唑醇水乳剂', '戊唑醇水乳剂是一种先进的超、低毒、光谱内吸杀菌剂', 700.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/9f0f1d18-dc66-4df6-88ca-25ee0c420b92.jpg', '2023-06-21 21:00:10', '苹果锈病', '2023-06-21 21:00:10');
INSERT INTO `shop_product` VALUES (10000115, 117, '病害治愈', '丙环唑乳油', '丙环唑乳油是一种农药杀菌剂', 700.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/e7fe8923-b661-4aaf-b624-27ddffe5a333.png', '2023-06-21 21:00:38', '苹果锈病', '2023-06-21 21:00:38');
INSERT INTO `shop_product` VALUES (10000116, 117, '病害治愈', '波尔多液', '波尔多液是无机铜素杀菌剂。', 400.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/bc39a5ce-ca66-48a4-b6b4-fdce624cbe0d.jpg', '2023-06-21 21:01:07', '苹果锈病', '2023-06-21 21:01:07');
INSERT INTO `shop_product` VALUES (10000117, 117, '病害治愈', '粉锈灵', '粉锈灵是一种高效、低毒、低残留、广谱性杀菌剂\n', 1200.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/44a88ab9-4c56-4799-a533-a48594d8b804.jpg', '2023-06-21 21:01:34', '苹果锈病', '2023-06-21 21:01:34');
INSERT INTO `shop_product` VALUES (10000118, 117, '病害治愈', '溴菌腈', '溴菌腈是一种低毒广谱兼有杀菌、防霉、灭藻性能的化合物，能抑制和铲除细菌、真菌及藻类的生长。', 1500.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/76168057-5081-42dc-a20e-3f44f526eb6c.jpg', '2023-06-21 21:04:53', '番茄早疫病', '2023-06-21 21:04:53');
INSERT INTO `shop_product` VALUES (10000119, 117, '病害治愈', '吡唑醚菌酯', '吡唑醚菌酯是一种广泛使用的广谱杀菌剂,它具有保护、治疗和渗透作用，并能提高作物的产量和品质。\n', 1100.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/67404d3e-1115-4832-b7b1-f906fbbd3941.jpg', '2023-06-21 21:05:24', '番茄早疫病', '2023-06-21 21:05:24');
INSERT INTO `shop_product` VALUES (10000120, 117, '病害治愈', '武夷菌素水剂', '武夷菌素是一种农用抗生素，主要通过抑制病菌蛋白质的合成，导致病菌死亡。\n', 600.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/5272f647-541e-4cd1-969c-9747559a96a3.jpg', '2023-06-21 21:05:50', '番茄早疫病', '2023-06-21 21:05:50');
INSERT INTO `shop_product` VALUES (10000121, 117, '病害治愈', '腐霉利可湿性粉剂', '腐霉利可湿性粉剂是一种杀菌剂，主要用于防治各种植物的真菌病害。\n', 1300.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/be8b5bf0-7a46-44dd-ac1d-a82e4b9459ca.jpg', '2023-06-21 21:06:24', '番茄早疫病', '2023-06-21 21:06:24');
INSERT INTO `shop_product` VALUES (10000122, 117, '病害治愈', '环菜酯', '环菜酯是一种广谱杀菌剂，属于三唑类化合物', 70.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/51a32e7e-6bf0-4c1b-8348-4af829144e1d.jpg', '2023-06-21 21:20:57', '番茄叶斑真菌', '2023-06-21 23:29:21');
INSERT INTO `shop_product` VALUES (10000123, 117, '病害治愈', '氧化锰', '氧化锰是一种无机化合物，是黑色固体', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/58ce3de4-c469-4226-a4f9-533f99c158e9.jpg', '2023-06-21 21:21:19', '番茄叶斑真菌', '2023-06-21 23:29:20');
INSERT INTO `shop_product` VALUES (10000124, 117, '病害治愈', '氟吡菌酯', '氟吡菌酯是一种广谱、高效的杀菌剂，属于二氢吡啶酮类化合物。', 35.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/4308f581-ea2b-453d-9005-48511c7009d5.jpg', '2023-06-21 21:21:50', '番茄叶斑真菌', '2023-06-21 23:29:20');
