INSERT INTO `shop_product` VALUES (10000128, 117, '病害治愈', '丙森锌', '丙森锌是一种广谱、速效、残效期长的保护性杀菌剂\n', 30.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/1d62fc66-54c2-4c00-8783-8173cf57ae60.jpg', '2023-06-21 21:34:24', '番茄叶霉病', '2023-06-21 23:29:20');
INSERT INTO `shop_product` VALUES (10000129, 117, '病害治愈', '烯唑醇', '烯唑醇是一种三唑类杀菌剂，具有保护、治疗和铲除作用，是广谱性杀菌剂\n', 12.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/6e277c24-4ab7-4127-891d-b803a19d3e12.jpg', '2023-06-21 21:34:48', '番茄叶霉病', '2023-06-21 23:29:20');
INSERT INTO `shop_product` VALUES (10000130, 117, '病害治愈', '除螨特', '除螨特是一种酮烯醇类杀螨剂，杀螨机理与一般杀螨剂完全不同。\n', 94.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/1324d6cb-08eb-4a89-970e-d914d9cb2843.png', '2023-06-21 21:41:27', '番茄蜘蛛螨伤害', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000131, 117, '病害治愈', '哒螨灵', '哒螨灵为广谱、触杀性杀螨剂，可用于防治多种植食性害螨', 14.99, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/7401328b-3e5b-48a2-bfc3-64924d11e920.png', '2023-06-21 21:42:13', '番茄蜘蛛螨伤害', '2023-07-02 19:03:24');
INSERT INTO `shop_product` VALUES (10000132, 117, '病害治愈', '苯丁锡', '苯丁锡是一种有机化合物，化学式为CHOSn₂，是一种杀螨剂', 100.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/045c4778-f10d-4bd4-b721-a9c497ae75cf.png', '2023-06-21 21:43:00', '番茄蜘蛛螨伤害', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000133, 117, '病害治愈', '炔螨特', '炔螨特是一种广谱有机硫杀螨剂，对成螨和若螨有特效', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/54124101-cd33-4993-8aee-a0497cd5e22d.png', '2023-06-21 21:44:15', '番茄蜘蛛螨伤害', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000134, 117, '病害治愈', '硫酸铜钙', '硫酸铜钙是一种广谱保护性杀菌剂，主要用于果树和蔬菜上的真菌病害。', 66.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8b6b91f3-2970-4696-a42d-dfc78237a663.png', '2023-06-21 21:56:43', '苹果棕斑病', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000135, 117, '病害治愈', '多氧霉素', '多氧霉素，也被称为多抗霉素，是一种由金色产色链霉菌自然发酵产生的水溶性抗生素。', 55.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/cf2c3d9a-75a0-4018-958b-ce3cb0f6267c.jpg', '2023-06-21 21:57:56', '苹果棕斑病', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000136, 117, '病害治愈', '多菌灵可湿性粉剂', '多菌灵可湿性粉剂是一种广谱性杀菌剂，主要用来预防和治疗多种植物病害。', 22.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/50766552-d6da-4c53-abad-db7da18cdad9.jpg', '2023-06-21 21:59:16', '苹果棕斑病', '2023-06-21 23:30:15');
INSERT INTO `shop_product` VALUES (10000137, 117, '病害治愈', '硫酸铜钙可湿性粉剂', '硫酸铜钙可湿性粉剂是一种广谱性的保护性杀菌剂，主要用来预防和治疗果树和蔬菜上的真菌病害。', 20.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/49c09dfe-e074-486d-aa34-34e92f6ad9a6.jpg', '2023-06-21 22:00:12', '苹果棕斑病', '2023-06-21 23:30:15');
INSERT INTO `shop_product` VALUES (10000138, 117, '病害治愈', '苯甲嘧菌酯', '苯甲嘧菌酯是一种高科技复配的杀菌剂', 10.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/2223268e-4b32-405e-bc65-39e3fcf8b7f0.png', '2023-06-21 22:06:53', '玉米锈病', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000139, 117, '病害治愈', '多·硫悬浮剂', '多·硫悬浮剂是一种复配剂，由多菌灵和硫磺混配而成，低毒，有效期2年', 150.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/f32f90d9-8d15-4c53-afdb-4688dd4e2ca5.png', '2023-06-21 22:07:59', '玉米锈病', '2023-06-21 23:30:15');
INSERT INTO `shop_product` VALUES (10000140, 117, '病害治愈', '固体石硫合剂', '固体石硫合剂是一种由石灰、硫磺和水熬制而成的碱性化合物，主要成分为四硫化钙和五硫化钙。', 130.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/48c99c6e-6123-4622-8324-e95e22f7673e.png', '2023-06-21 22:08:57', '玉米锈病', '2023-06-21 23:30:15');
INSERT INTO `shop_product` VALUES (10000141, 117, '病害治愈', '啶虫脒', '啶虫脒是一种新型杀虫剂，具有触杀、胃毒和内吸作用', 24.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/ea8da41c-be1b-431e-9230-039c41695a47.png', '2023-06-21 22:10:31', '玉米锈病', '2023-06-21 23:30:16');
INSERT INTO `shop_product` VALUES (10000142, 117, '病害治愈', '恩诺菌酯', '炭疽福美的主要成分是氧化亚铜（copper oxychloride），它具有广谱的杀菌活性。通过破坏病原真菌细胞膜，阻断其代谢过程，从而抑制炭疽病菌的生长和繁殖。', 4.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/7bfcd5ef-7003-43e1-9559-eaffc32d3377.jpg', '2023-07-01 22:24:25', '苹果灰斑病', '2023-07-02 13:48:54');
INSERT INTO `shop_product` VALUES (10000143, 117, '病害治愈', '恩诺沙星', '恩诺沙星（Enrofloxacin）是一种广谱抗生素，属于氟喹诺酮类药物。它具有强大的抗菌活性', 90.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/8527963b-a1b3-41a4-9996-763e90cfbcbf.jpeg', '2023-07-01 22:26:25', '苹果灰斑病', '2023-07-02 13:48:58');
INSERT INTO `shop_product` VALUES (10000144, 117, '病害治愈', '敌草快', '敌草快（Glyphosate）是一种广泛使用的除草剂，属于非选择性的有机磷酸盐除草剂。', 15.00, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/98feba0e-99ae-4035-99d3-c504943f7e40.jpg', '2023-07-01 22:28:10', '苹果灰斑病', '2023-07-02 13:49:03');
INSERT INTO `shop_product` VALUES (10000145, 117, '病害治愈', '哒螨灵', '哒螨灵（Avermectin）是一类高效的驱虫剂，属于宏观有机杀虫剂，可用于防治多种植食性害螨', 14.99, 1, 'https://etrees.oss-cn-shanghai.aliyuncs.com/49a794a0-f55e-470a-8da9-b5409d9dd941.jpg', '2023-07-01 22:30:37', '苹果灰斑病', '2023-07-02 19:05:31');
